-- Forward-only corrections for all 85 reviewed visual questions.
--
-- Migrations 003, 009 and 013 are already live and must remain byte-for-byte
-- immutable. This migration updates only reviewed question content and leaves
-- teacher-managed active/plan/locked-display controls unchanged.

do $visuals$
declare
  updated_count integer;
begin
  with source (
    lesson_slug, stable_key, position, section, format, payload,
    is_original, points
  ) as (
    values
      ('july-04', 'july-04-extra-visual-1', 44, 'See It', 'situation', '{"id":"july-04-extra-visual-1","format":"situation","type":"situation","section":"See It","topic":"safety","isOriginal":false,"hint":"Notice the person’s tiredness, the keys left behind, and the transport chosen instead.","hintJa":"人物の疲れ、置いていく車の鍵、代わりに選ぶ交通手段に注目しましょう。","explanation":"“I avoid driving when I’m tired.” is correct. Because the person is tired, the car keys stay on the hook and a transit card is taken instead. “Actually, I’m a little tired today.” does not fit because tiredness is only the reason; the key evidence is the deliberate choice not to drive. “Something came up.” does not fit because no unexpected call or emergency interrupts a plan; the person makes a safety choice. “It might rain later.” does not fit because no clouds or umbrella suggest future rain; the scene concerns fatigue and driving.","explanationJa":"正解は「I avoid driving when I’m tired.」（疲れている時は運転を避けます。）です。疲れているため車の鍵を置き、代わりに交通カードを持って電車を選んでいます。 「Actually, I’m a little tired today.」はこの場面とは一致しません。疲れは理由にすぎず、重要なのは運転しない選択をしていることです。 「Something came up.」はこの場面とは一致しません。急な連絡や予定の中断ではなく、安全のために移動手段を選んでいます。 「It might rain later.」はこの場面とは一致しません。雲や傘はなく、場面の中心は疲労と運転です。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"I avoid driving when I’m tired.","jp":"疲れている時は運転を避けます。"},{"id":"b","en":"Actually, I’m a little tired today.","jp":"実は今日は少し疲れています。"},{"id":"c","en":"Something came up.","jp":"急な事情ができました。"},{"id":"d","en":"It might rain later.","jp":"あとで雨が降るかもしれません。"}],"correct":"a","image":"/assets/questions/visual/july-04-01-avoid-driving-tired.webp","imageAlt":"A tired person leaves the car keys at home and chooses the train.","visualAssetId":"july-04-01"}'::jsonb, false, 1),
      ('july-04', 'july-04-extra-visual-2', 45, 'See It', 'situation', '{"id":"july-04-extra-visual-2","format":"situation","type":"situation","section":"See It","topic":"unexpected events","isOriginal":false,"hint":"Look at the prepared appointment items and the urgent interruption that stops the person leaving.","hintJa":"準備済みの予定の持ち物と、出発を止める急な出来事を見ましょう。","explanation":"“Something came up.” is correct. The person is ready for an appointment but an urgent phone call unexpectedly interrupts the plan. “Actually, I’m a little tired today.” does not fit because the person looks surprised by a call, not physically tired. “It can’t be helped.” does not fit because the visual shows the unexpected event itself, not a calm acceptance after it. “I really appreciate it.” does not fit because no one is being thanked for help; the appointment is interrupted by urgent news.","explanationJa":"正解は「Something came up.」（急な事情ができました。）です。約束へ出かける準備を終えた人物が、突然の緊急電話で足を止めています。 「Actually, I’m a little tired today.」はこの場面とは一致しません。疲れた様子ではなく、電話に驚いています。 「It can’t be helped.」はこの場面とは一致しません。出来事を諦めて受け入れる反応ではなく、急な出来事そのものが描かれています。 「I really appreciate it.」はこの場面とは一致しません。助けへの感謝ではなく、緊急連絡で予定が中断されています。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"Something came up.","jp":"急な事情ができました。"},{"id":"b","en":"Actually, I’m a little tired today.","jp":"実は今日は少し疲れています。"},{"id":"c","en":"It can’t be helped.","jp":"仕方ありません。"},{"id":"d","en":"I really appreciate it.","jp":"本当に感謝しています。"}],"correct":"a","image":"/assets/questions/visual/july-04-02-something-came-up.webp","imageAlt":"An urgent phone call unexpectedly interrupts a planned appointment.","visualAssetId":"july-04-02"}'::jsonb, false, 1),
      ('july-04', 'july-04-extra-visual-3', 46, 'See It', 'situation', '{"id":"july-04-extra-visual-3","format":"situation","type":"situation","section":"See It","topic":"intention","isOriginal":false,"hint":"Use the caught bag, sudden spill, and immediate apologetic reaction to judge intent.","hintJa":"引っ掛かったかばん、突然のこぼれ、すぐ謝る反応から意図があったか考えましょう。","explanation":"“He didn’t do it on purpose.” is correct. His bag catches the table by accident, and he immediately apologizes and helps clean the spill. “Something came up.” does not fit because there is no outside emergency changing a plan; the visible event is an accidental spill. “It can’t be helped.” does not fit because the man is actively apologizing for the accident, not merely accepting an unavoidable situation. “I really appreciate it.” does not fit because his open hands show apology and surprise, not thanks for receiving help.","explanationJa":"正解は「He didn’t do it on purpose.」（彼はわざとしたのではありません。）です。かばんが偶然テーブルに引っ掛かり、男性はすぐ謝って片付けようとしています。 「Something came up.」はこの場面とは一致しません。予定を変える急用ではなく、目の前で偶然飲み物をこぼしています。 「It can’t be helped.」はこの場面とは一致しません。仕方ないと受け流すのではなく、事故について積極的に謝っています。 「I really appreciate it.」はこの場面とは一致しません。手の動きは助けへの感謝ではなく、驚きと謝罪を示しています。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"He didn’t do it on purpose.","jp":"彼はわざとしたのではありません。"},{"id":"b","en":"Something came up.","jp":"急な事情ができました。"},{"id":"c","en":"It can’t be helped.","jp":"仕方ありません。"},{"id":"d","en":"I really appreciate it.","jp":"本当に感謝しています。"}],"correct":"a","image":"/assets/questions/visual/july-04-03-not-on-purpose.webp","imageAlt":"A man accidentally bumps a table and apologizes for spilling a drink.","visualAssetId":"july-04-03"}'::jsonb, false, 1),
      ('july-04', 'july-04-extra-visual-4', 47, 'See It', 'situation', '{"id":"july-04-extra-visual-4","format":"situation","type":"situation","section":"See It","topic":"gratitude","isOriginal":false,"hint":"Notice the heavy boxes, the helper, and the recipient’s hand-over-heart bow.","hintJa":"重い箱、手伝った人、胸に手を当ててお辞儀する受け手を見ましょう。","explanation":"“I really appreciate it.” is correct. One person has carried heavy boxes, and the recipient gives a sincere hand-over-heart thank-you. “Actually, I’m a little tired today.” does not fit because the recipient’s expression and bow communicate gratitude, not a complaint about tiredness. “It can’t be helped.” does not fit because the scene celebrates helpful effort rather than accepting an unavoidable setback. “Don’t mention it.” does not fit because the grateful recipient is speaking first; this would be the helper’s reply after being thanked.","explanationJa":"正解は「I really appreciate it.」（本当に感謝しています。）です。一人が重い箱を運び、助けてもらった人が胸に手を当てて心から感謝しています。 「Actually, I’m a little tired today.」はこの場面とは一致しません。表情とお辞儀は疲れの訴えではなく感謝を表しています。 「It can’t be helped.」はこの場面とは一致しません。避けられない不運を受け入れるのではなく、助けてもらったことを喜んでいます。 「Don’t mention it.」はこの場面とは一致しません。話しているのは感謝する側で、この表現は感謝された側の返答です。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"I really appreciate it.","jp":"本当に感謝しています。"},{"id":"b","en":"Actually, I’m a little tired today.","jp":"実は今日は少し疲れています。"},{"id":"c","en":"It can’t be helped.","jp":"仕方ありません。"},{"id":"d","en":"Don’t mention it.","jp":"どういたしまして。"}],"correct":"a","image":"/assets/questions/visual/july-04-04-appreciate-help.webp","imageAlt":"A grateful person sincerely thanks someone who helped carry heavy boxes.","visualAssetId":"july-04-04"}'::jsonb, false, 1),
      ('july-04', 'july-04-extra-visual-5', 48, 'See It', 'situation', '{"id":"july-04-extra-visual-5","format":"situation","type":"situation","section":"See It","topic":"possibility","isOriginal":false,"hint":"Check the dry street, gathering clouds, and the umbrella packed before leaving.","hintJa":"まだ乾いた道、集まる雨雲、出発前に入れる傘を確認しましょう。","explanation":"“It might rain later.” is correct. The street is still dry, but dark clouds lead the person to pack an umbrella for a possible later shower. “Actually, I’m a little tired today.” does not fit because the person is preparing for weather, with no sign of fatigue. “I avoid driving when I’m tired.” does not fit because no car keys, car, or transport choice appears; the visible decision concerns an umbrella. “I really appreciate it.” does not fit because no helper or thankful exchange is present; the person is watching the clouds.","explanationJa":"正解は「It might rain later.」（あとで雨が降るかもしれません。）です。道はまだ乾いていますが、黒い雲を見て、あとで降るかもしれない雨に備えて傘を入れています。 「Actually, I’m a little tired today.」はこの場面とは一致しません。疲れた様子ではなく、天候に備えています。 「I avoid driving when I’m tired.」はこの場面とは一致しません。車や鍵、交通手段の選択はなく、傘を持つ判断が描かれています。 「I really appreciate it.」はこの場面とは一致しません。手伝う人や感謝のやり取りはなく、雲を見ています。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"It might rain later.","jp":"あとで雨が降るかもしれません。"},{"id":"b","en":"Actually, I’m a little tired today.","jp":"実は今日は少し疲れています。"},{"id":"c","en":"I avoid driving when I’m tired.","jp":"疲れている時は運転を避けます。"},{"id":"d","en":"I really appreciate it.","jp":"本当に感謝しています。"}],"correct":"a","image":"/assets/questions/visual/july-04-05-might-rain.webp","imageAlt":"A person notices dark clouds and carries an umbrella because it might rain later.","visualAssetId":"july-04-05"}'::jsonb, false, 1),
      ('july-05', 'july-05-extra-visual-1', 41, 'See It', 'situation', '{"id":"july-05-extra-visual-1","format":"situation","type":"situation","section":"See It","topic":"preferences","isOriginal":false,"hint":"Compare the warm indoor choice with the invitation to go out in the rain.","hintJa":"雨の中の外出の誘いと、暖かい室内で選んだ過ごし方を比べましょう。","explanation":"“I’d rather stay home tonight.” is correct. The person cheerfully waves friends goodbye and settles in at home with tea and a book. “It depends on the weather.” does not fit because the person has already chosen to stay in, rather than waiting for weather before deciding. “Let me think about it.” does not fit because the relaxed setup and goodbye wave show a completed decision, not a request for thinking time. “Either option works for me.” does not fit because the home option is clearly preferred over going out; the two choices are not equally accepted.","explanationJa":"正解は「I’d rather stay home tonight.」（今夜は家にいたいです。）です。人物は友人を笑顔で見送り、家でお茶と本を楽しむことを選んでいます。 「It depends on the weather.」はこの場面とは一致しません。天気を見て決めるのではなく、すでに家にいることを選んでいます。 「Let me think about it.」はこの場面とは一致しません。くつろぐ準備と別れの手振りは決定済みで、考える時間を求めてはいません。 「Either option works for me.」はこの場面とは一致しません。外出より家を明確に選んでおり、二つを同じように受け入れてはいません。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"I’d rather stay home tonight.","jp":"今夜は家にいたいです。"},{"id":"b","en":"It depends on the weather.","jp":"天気によります。"},{"id":"c","en":"Let me think about it.","jp":"少し考えさせてください。"},{"id":"d","en":"Either option works for me.","jp":"どちらの選択肢でも大丈夫です。"}],"correct":"a","image":"/assets/questions/visual/july-05-01-rather-stay-home.webp","imageAlt":"A person chooses a cozy evening at home instead of going out.","visualAssetId":"july-05-01"}'::jsonb, false, 1),
      ('july-05', 'july-05-extra-visual-2', 42, 'See It', 'situation', '{"id":"july-05-extra-visual-2","format":"situation","type":"situation","section":"See It","topic":"decisions","isOriginal":false,"hint":"Notice why the picnic basket stays ready while the final decision is delayed.","hintJa":"ピクニックかごを持ったまま、何を理由に最終決定を待っているか見ましょう。","explanation":"“It depends on the weather.” is correct. The picnic decision is paused while the person compares sunny and rainy forecasts. “That makes sense.” does not fit because no explanation is being accepted; two weather outcomes are controlling a future plan. “I’m not sure yet.” does not fit because this only states uncertainty and misses the visible reason: the weather forecast. “I changed my mind.” does not fit because no earlier choice is being replaced; the person is waiting for forecast information.","explanationJa":"正解は「It depends on the weather.」（天気によります。）です。人物は晴れと雨の予報を比べ、ピクニックの決定を保留しています。 「That makes sense.」はこの場面とは一致しません。説明に納得しているのではなく、二つの天候が今後の予定を左右しています。 「I’m not sure yet.」はこの場面とは一致しません。単なる未決定では、画面に示された天気という理由を説明できません。 「I changed my mind.」はこの場面とは一致しません。以前の選択を変更しておらず、予報を見て判断を待っています。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"It depends on the weather.","jp":"天気によります。"},{"id":"b","en":"That makes sense.","jp":"なるほど、筋が通っています。"},{"id":"c","en":"I’m not sure yet.","jp":"まだ分かりません。"},{"id":"d","en":"I changed my mind.","jp":"考えが変わりました。"}],"correct":"a","image":"/assets/questions/visual/july-05-02-depends-weather.webp","imageAlt":"A person waits to decide on a picnic after comparing sunny and rainy weather.","visualAssetId":"july-05-02"}'::jsonb, false, 1),
      ('july-05', 'july-05-extra-visual-3', 43, 'See It', 'situation', '{"id":"july-05-extra-visual-3","format":"situation","type":"situation","section":"See It","topic":"decisions","isOriginal":false,"hint":"Read the shopper’s hand-on-chin pose and the gesture asking for a moment.","hintJa":"あごに手を当てた姿勢と、少し待ってほしいという手の動きを読み取りましょう。","explanation":"“Let me think about it.” is correct. Faced with two items, the shopper pauses and signals for time before choosing. “That makes sense.” does not fit because the shopper is weighing options, not agreeing that another person’s explanation is logical. “That’s a good point.” does not fit because no argument or useful point is being acknowledged; the focus is a personal decision. “Either option works for me.” does not fit because the thoughtful pause shows the options are not yet equally acceptable.","explanationJa":"正解は「Let me think about it.」（少し考えさせてください。）です。二つの商品を前に、買い物客は選ぶ前に考える時間を求めています。 「That makes sense.」はこの場面とは一致しません。相手の説明に納得しているのではなく、選択肢を検討しています。 「That’s a good point.」はこの場面とは一致しません。意見の良さを認める会話ではなく、自分の選択を考えています。 「Either option works for me.」はこの場面とは一致しません。考え込む様子から、どちらでも同じように良いとは決めていません。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"Let me think about it.","jp":"少し考えさせてください。"},{"id":"b","en":"That makes sense.","jp":"なるほど、筋が通っています。"},{"id":"c","en":"That’s a good point.","jp":"それはいい指摘ですね。"},{"id":"d","en":"Either option works for me.","jp":"どちらの選択肢でも大丈夫です。"}],"correct":"a","image":"/assets/questions/visual/july-05-03-let-me-think.webp","imageAlt":"A shopper pauses thoughtfully before choosing between two options.","visualAssetId":"july-05-03"}'::jsonb, false, 1),
      ('july-05', 'july-05-extra-visual-4', 44, 'See It', 'situation', '{"id":"july-05-extra-visual-4","format":"situation","type":"situation","section":"See It","topic":"choices","isOriginal":false,"hint":"Follow the diner’s hand from the first dish toward the newly selected dish.","hintJa":"最初の料理から、新しく選び直した料理へ向かう手の動きを追いましょう。","explanation":"“I changed my mind.” is correct. The diner moves away from the original dish and points to a different final choice. “I’d rather stay home tonight.” does not fit because the setting is a restaurant choice, not a decision between home and going out. “I’m not sure yet.” does not fit because the pointing gesture identifies a new choice, so the diner is no longer undecided. “That’s a good point.” does not fit because no opinion is being praised; one menu choice replaces another.","explanationJa":"正解は「I changed my mind.」（考えが変わりました。）です。客は最初の料理をやめ、別の料理を最終的に指して選び直しています。 「I’d rather stay home tonight.」はこの場面とは一致しません。家にいるか外出するかではなく、レストランで料理を選んでいます。 「I’m not sure yet.」はこの場面とは一致しません。指差しで新しい選択を示しているため、まだ決めていない状態ではありません。 「That’s a good point.」はこの場面とは一致しません。意見を評価しているのではなく、料理の選択を変更しています。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"I changed my mind.","jp":"考えが変わりました。"},{"id":"b","en":"I’d rather stay home tonight.","jp":"今夜は家にいたいです。"},{"id":"c","en":"I’m not sure yet.","jp":"まだ分かりません。"},{"id":"d","en":"That’s a good point.","jp":"それはいい指摘ですね。"}],"correct":"a","image":"/assets/questions/visual/july-05-04-changed-mind.webp","imageAlt":"A diner changes from choosing one dish to choosing another.","visualAssetId":"july-05-04"}'::jsonb, false, 1),
      ('july-05', 'july-05-extra-visual-5', 45, 'See It', 'situation', '{"id":"july-05-extra-visual-5","format":"situation","type":"situation","section":"See It","topic":"choices","isOriginal":false,"hint":"Compare the person’s equally positive reaction to the two appointment choices.","hintJa":"二つの予定候補に対する、人物の同じように前向きな反応を比べましょう。","explanation":"“Either option works for me.” is correct. The person gives equal approval to both appointment options with no preference between them. “I’d rather stay home tonight.” does not fit because the options are appointment times, not staying home versus going out. “It depends on the weather.” does not fit because no forecast or weather condition affects the equal approval. “I changed my mind.” does not fit because neither option replaces an earlier decision; both remain acceptable.","explanationJa":"正解は「Either option works for me.」（どちらの選択肢でも大丈夫です。）です。人物は二つの予定候補を同じように承認し、どちらにも偏っていません。 「I’d rather stay home tonight.」はこの場面とは一致しません。選択肢は予定の日時で、家にいるか外出するかではありません。 「It depends on the weather.」はこの場面とは一致しません。予報や天候条件はなく、両方を同等に承認しています。 「I changed my mind.」はこの場面とは一致しません。以前の決定を変えたのではなく、両方とも受け入れています。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"Either option works for me.","jp":"どちらの選択肢でも大丈夫です。"},{"id":"b","en":"I’d rather stay home tonight.","jp":"今夜は家にいたいです。"},{"id":"c","en":"It depends on the weather.","jp":"天気によります。"},{"id":"d","en":"I changed my mind.","jp":"考えが変わりました。"}],"correct":"a","image":"/assets/questions/visual/july-05-05-either-option.webp","imageAlt":"A person happily accepts either of two appointment options.","visualAssetId":"july-05-05"}'::jsonb, false, 1),
      ('july-06', 'july-06-extra-visual-1', 51, 'See It', 'situation', '{"id":"july-06-extra-visual-1","format":"situation","type":"situation","section":"See It","topic":"clarification","isOriginal":false,"hint":"Notice the learner’s listening gesture and the request directed back to the speaker.","hintJa":"聞き手の耳に向けた動作と、話し手に返している依頼に注目しましょう。","explanation":"“Could you say that again?” is correct. The learner did not catch the utterance and politely asks the speaker to repeat it. “What do you mean?” does not fit because the gesture asks to hear the words again, not to explain their meaning. “Can you give me an example?” does not fit because no example or demonstration is requested; the original speech needs repeating. “That’s the part I find difficult.” does not fit because the learner does not point to a difficult section; attention remains on the speaker’s utterance.","explanationJa":"正解は「Could you say that again?」（もう一度言っていただけますか？）です。学習者は発言を聞き取れず、話し手に丁寧に繰り返してもらおうとしています。 「What do you mean?」はこの場面とは一致しません。意味の説明ではなく、言葉をもう一度聞くための動作です。 「Can you give me an example?」はこの場面とは一致しません。例や実演を求めておらず、元の発言の繰り返しが必要です。 「That’s the part I find difficult.」はこの場面とは一致しません。難しい箇所を指しておらず、話し手の発言に注意を向けています。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"Could you say that again?","jp":"もう一度言っていただけますか？"},{"id":"b","en":"What do you mean?","jp":"どういう意味ですか？"},{"id":"c","en":"Can you give me an example?","jp":"例を一つ教えてもらえますか？"},{"id":"d","en":"That’s the part I find difficult.","jp":"そこが難しいと感じる部分です。"}],"correct":"a","image":"/assets/questions/visual/july-06-01-say-again.webp","imageAlt":"A learner politely asks a speaker to repeat what was said.","visualAssetId":"july-06-01"}'::jsonb, false, 1),
      ('july-06', 'july-06-extra-visual-2', 52, 'See It', 'situation', '{"id":"july-06-extra-visual-2","format":"situation","type":"situation","section":"See It","topic":"change","isOriginal":false,"hint":"Compare the commuter’s earlier discomfort with the calmer response after repeated trips.","hintJa":"以前の不安そうな様子と、何度も乗った後の落ち着いた様子を比べましょう。","explanation":"“I’m getting used to it.” is correct. Across repeated crowded-train trips, the commuter becomes progressively calmer and more comfortable. “I’ve never tried that before.” does not fit because the sequence shows repeated experience, not a first attempt. “It was better than I expected.” does not fit because the evidence shows gradual adjustment over time, not one experience exceeding an expectation. “That’s the part I find difficult.” does not fit because no task section is identified; the change concerns comfort with train crowds.","explanationJa":"正解は「I’m getting used to it.」（だんだん慣れてきました。）です。混雑した電車に何度も乗るうちに、通勤者は徐々に慣れ、落ち着いてきています。 「I’ve never tried that before.」はこの場面とは一致しません。何度も経験している流れで、初めて試す場面ではありません。 「It was better than I expected.」はこの場面とは一致しません。一度の経験が予想以上だったのではなく、時間をかけて順応しています。 「That’s the part I find difficult.」はこの場面とは一致しません。課題の難所ではなく、電車の混雑への慣れが描かれています。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"I’m getting used to it.","jp":"だんだん慣れてきました。"},{"id":"b","en":"I’ve never tried that before.","jp":"それは今まで試したことがありません。"},{"id":"c","en":"It was better than I expected.","jp":"思っていたより良かったです。"},{"id":"d","en":"That’s the part I find difficult.","jp":"そこが難しいと感じる部分です。"}],"correct":"a","image":"/assets/questions/visual/july-06-02-getting-used-to-it.webp","imageAlt":"A commuter becomes more comfortable using a crowded train over time.","visualAssetId":"july-06-02"}'::jsonb, false, 1),
      ('july-06', 'july-06-extra-visual-3', 53, 'See It', 'situation', '{"id":"july-06-extra-visual-3","format":"situation","type":"situation","section":"See It","topic":"experience","isOriginal":false,"hint":"Use the untouched clay, beginner’s hesitation, and first instruction from the teacher.","hintJa":"まだ手を付けていない粘土、初心者のためらい、先生の最初の説明を見ましょう。","explanation":"“I’ve never tried that before.” is correct. The beginner approaches pottery hesitantly and is about to attempt it for the first time. “I’m getting used to it.” does not fit because the person is just beginning and has not had repeated practice to become accustomed. “It was better than I expected.” does not fit because the activity has not been completed, so no after-the-fact evaluation is visible. “I’ll check and let you know.” does not fit because no information is being checked for a later reply; a new craft is being attempted.","explanationJa":"正解は「I’ve never tried that before.」（それは今まで試したことがありません。）です。初心者はためらいながら陶芸に向き合い、初めて挑戦しようとしています。 「I’m getting used to it.」はこの場面とは一致しません。始めたばかりで、慣れるほど繰り返し練習していません。 「It was better than I expected.」はこの場面とは一致しません。まだ体験を終えておらず、結果を予想と比べる場面ではありません。 「I’ll check and let you know.」はこの場面とは一致しません。後で知らせるための確認ではなく、新しい作業に挑戦しています。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"I’ve never tried that before.","jp":"それは今まで試したことがありません。"},{"id":"b","en":"I’m getting used to it.","jp":"だんだん慣れてきました。"},{"id":"c","en":"It was better than I expected.","jp":"思っていたより良かったです。"},{"id":"d","en":"I’ll check and let you know.","jp":"確認してお知らせします。"}],"correct":"a","image":"/assets/questions/visual/july-06-03-never-tried-before.webp","imageAlt":"A beginner hesitantly tries pottery for the first time.","visualAssetId":"july-06-03"}'::jsonb, false, 1),
      ('july-06', 'july-06-extra-visual-4', 54, 'See It', 'situation', '{"id":"july-06-extra-visual-4","format":"situation","type":"situation","section":"See It","topic":"learning","isOriginal":false,"hint":"Look at the learner asking the teacher to show one concrete case on the board.","hintJa":"学習者が先生に、板上で具体的な一例を示してほしいと頼む様子を見ましょう。","explanation":"“Can you give me an example?” is correct. The learner requests one concrete demonstration, and the teacher is ready to illustrate it. “Could you say that again?” does not fit because the learner wants a concrete demonstration, not repetition of the same words. “What do you mean?” does not fit because the request is for a sample case, more specific than a general meaning question. “I’ll check and let you know.” does not fit because the teacher is being asked to demonstrate now, not check information and reply later.","explanationJa":"正解は「Can you give me an example?」（例を一つ教えてもらえますか？）です。学習者は具体的な実演を一つ求め、先生は示す準備をしています。 「Could you say that again?」はこの場面とは一致しません。同じ言葉の繰り返しではなく、具体的な実演を求めています。 「What do you mean?」はこの場面とは一致しません。一般的な意味の質問ではなく、具体例を求めています。 「I’ll check and let you know.」はこの場面とは一致しません。後で確認して返答するのではなく、今その場で示すよう頼まれています。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"Can you give me an example?","jp":"例を一つ教えてもらえますか？"},{"id":"b","en":"Could you say that again?","jp":"もう一度言っていただけますか？"},{"id":"c","en":"What do you mean?","jp":"どういう意味ですか？"},{"id":"d","en":"I’ll check and let you know.","jp":"確認してお知らせします。"}],"correct":"a","image":"/assets/questions/visual/july-06-04-give-example.webp","imageAlt":"A learner asks a teacher to demonstrate one concrete example.","visualAssetId":"july-06-04"}'::jsonb, false, 1),
      ('july-06', 'july-06-extra-visual-5', 55, 'See It', 'situation', '{"id":"july-06-extra-visual-5","format":"situation","type":"situation","section":"See It","topic":"learning","isOriginal":false,"hint":"Notice that most work is complete and only one step is being pointed out.","hintJa":"ほとんどの作業は終わり、一つの手順だけを指している点に注目しましょう。","explanation":"“That’s the part I find difficult.” is correct. The learner points to one unresolved step within otherwise completed work. “Could you say that again?” does not fit because the problem is a visible work step, not unheard speech. “It was better than I expected.” does not fit because the learner is identifying an ongoing difficulty, not evaluating a finished result positively. “Can you give me an example?” does not fit because the gesture isolates a difficult part; it does not ask for a separate example.","explanationJa":"正解は「That’s the part I find difficult.」（そこが難しいと感じる部分です。）です。学習者はほぼ完成した作業の中で、解決できない一つの手順を指しています。 「Could you say that again?」はこの場面とは一致しません。問題は目に見える作業手順で、聞き取れなかった発言ではありません。 「It was better than I expected.」はこの場面とは一致しません。完成結果を良く評価するのではなく、残る難点を示しています。 「Can you give me an example?」はこの場面とは一致しません。難しい部分を特定しており、別の例を求めてはいません。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"That’s the part I find difficult.","jp":"そこが難しいと感じる部分です。"},{"id":"b","en":"Could you say that again?","jp":"もう一度言っていただけますか？"},{"id":"c","en":"It was better than I expected.","jp":"思っていたより良かったです。"},{"id":"d","en":"Can you give me an example?","jp":"例を一つ教えてもらえますか？"}],"correct":"a","image":"/assets/questions/visual/july-06-05-difficult-part.webp","imageAlt":"A learner points to one difficult step in otherwise completed work.","visualAssetId":"july-06-05"}'::jsonb, false, 1),
      ('june-28', 'june-28-extra-visual-1', 38, 'See It', 'situation', '{"id":"june-28-extra-visual-1","format":"situation","type":"situation","section":"See It","topic":"polite orders","isOriginal":false,"hint":"Focus on the drink the customer is requesting and the polite exchange at the counter.","hintJa":"カウンターで、客がどの飲み物を丁寧に頼んでいるかに注目しましょう。","explanation":"“I’d like a coffee, please.” is correct. The customer is politely requesting coffee while the server prepares to take the order. “It can’t be helped.” does not fit because no one is accepting an unavoidable problem; a café order is taking place. “Could I have the menu?” does not fit because the customer is asking for coffee, not requesting a menu. “Would you like anything else?” does not fit because the customer is making the request; the server is not offering an additional item after an order.","explanationJa":"正解は「I’d like a coffee, please.」（コーヒーをお願いします。）です。客が店員にコーヒーを丁寧に注文している場面です。 「It can’t be helped.」はこの場面とは一致しません。避けられない問題を受け入れる場面ではなく、カフェで注文しています。 「Could I have the menu?」はこの場面とは一致しません。メニューを求めているのではなく、コーヒーを注文しています。 「Would you like anything else?」はこの場面とは一致しません。追加注文を店員が尋ねているのではなく、客が飲み物を頼んでいます。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"I’d like a coffee, please.","jp":"コーヒーをお願いします。"},{"id":"b","en":"It can’t be helped.","jp":"仕方ありません。"},{"id":"c","en":"Could I have the menu?","jp":"メニューをいただけますか？"},{"id":"d","en":"Would you like anything else?","jp":"ほかに何かいかがですか？"}],"correct":"a","image":"/assets/questions/visual/june-28-01-order-coffee.webp","imageAlt":"A customer politely orders a cup of coffee from a café server.","visualAssetId":"june-28-01"}'::jsonb, false, 1),
      ('june-28', 'june-28-extra-visual-2', 39, 'See It', 'situation', '{"id":"june-28-extra-visual-2","format":"situation","type":"situation","section":"See It","topic":"useful responses","isOriginal":false,"hint":"Notice the cancelled journey and the traveler’s calm, resigned reaction.","hintJa":"運休になった移動予定と、旅行者の落ち着いた諦めの表情を見ましょう。","explanation":"“It can’t be helped.” is correct. The train is cancelled, and the traveler responds with a calm shrug instead of trying to change it. “I’d like a coffee, please.” does not fit because there is no café drink order; the visible problem is a cancelled train. “Could I have the menu?” does not fit because no diner or menu is shown at the station. “That sounds good.” does not fit because the traveler looks resigned about bad news, not pleased by an appealing suggestion.","explanationJa":"正解は「It can’t be helped.」（仕方ありません。）です。列車が運休となり、旅行者は状況を変えようとせず静かに受け入れています。 「I’d like a coffee, please.」はこの場面とは一致しません。カフェで飲み物を注文しておらず、見えている問題は列車の運休です。 「Could I have the menu?」はこの場面とは一致しません。駅の場面に食事客やメニューは描かれていません。 「That sounds good.」はこの場面とは一致しません。魅力的な提案に賛成しているのではなく、悪い知らせを諦めて受け止めています。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"It can’t be helped.","jp":"仕方ありません。"},{"id":"b","en":"I’d like a coffee, please.","jp":"コーヒーをお願いします。"},{"id":"c","en":"Could I have the menu?","jp":"メニューをいただけますか？"},{"id":"d","en":"That sounds good.","jp":"それはよさそうですね。"}],"correct":"a","image":"/assets/questions/visual/june-28-02-cant-be-helped.webp","imageAlt":"A traveler calmly accepts that a train has been cancelled.","visualAssetId":"june-28-02"}'::jsonb, false, 1),
      ('june-28', 'june-28-extra-visual-3', 40, 'See It', 'situation', '{"id":"june-28-extra-visual-3","format":"situation","type":"situation","section":"See It","topic":"restaurants","isOriginal":false,"hint":"Look at what the seated diner is asking the server to hand over.","hintJa":"座っている客が店員に何を渡してほしいと頼んでいるかを見ましょう。","explanation":"“Could I have the menu?” is correct. The diner gestures toward the menu held by the server and politely asks to receive it. “I’d like a coffee, please.” does not fit because the requested object is the menu, not a cup of coffee. “I ordered tea instead.” does not fit because no tea replacement has been chosen; the diner has not yet received the menu. “Would you like anything else?” does not fit because the diner is asking the server for something, rather than the server offering an extra item.","explanationJa":"正解は「Could I have the menu?」（メニューをいただけますか？）です。客は店員が持つメニューを指し、渡してもらうよう丁寧に頼んでいます。 「I’d like a coffee, please.」はこの場面とは一致しません。求めている物はコーヒーではなくメニューです。 「I ordered tea instead.」はこの場面とは一致しません。紅茶への変更は示されておらず、客はまだメニューを受け取ろうとしています。 「Would you like anything else?」はこの場面とは一致しません。店員が追加注文を尋ねているのではなく、客が店員に依頼しています。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"Could I have the menu?","jp":"メニューをいただけますか？"},{"id":"b","en":"I’d like a coffee, please.","jp":"コーヒーをお願いします。"},{"id":"c","en":"I ordered tea instead.","jp":"代わりに紅茶を注文しました。"},{"id":"d","en":"Would you like anything else?","jp":"ほかに何かいかがですか？"}],"correct":"a","image":"/assets/questions/visual/june-28-03-request-menu.webp","imageAlt":"A diner politely asks a server for the menu.","visualAssetId":"june-28-03"}'::jsonb, false, 1),
      ('june-28', 'june-28-extra-visual-4', 41, 'See It', 'situation', '{"id":"june-28-extra-visual-4","format":"situation","type":"situation","section":"See It","topic":"choices","isOriginal":false,"hint":"Compare the drink the customer keeps with the one being moved aside.","hintJa":"客が選んだ飲み物と、脇へよけた飲み物を比べましょう。","explanation":"“I ordered tea instead.” is correct. The customer keeps the tea and moves the offered coffee aside, showing a replacement choice. “I’d like a coffee, please.” does not fit because coffee is being rejected, while tea is the chosen drink. “What did you order?” does not fit because the image shows the completed choice, not a question asking what was ordered. “That sounds good.” does not fit because there is no response to a suggestion; the visible evidence is a switch from coffee to tea.","explanationJa":"正解は「I ordered tea instead.」（代わりに紅茶を注文しました。）です。客は紅茶を選び、提示されたコーヒーを脇へよけて変更を示しています。 「I’d like a coffee, please.」はこの場面とは一致しません。コーヒーは断られ、紅茶が選ばれています。 「What did you order?」はこの場面とは一致しません。何を注文したか尋ねる場面ではなく、選択した結果が示されています。 「That sounds good.」はこの場面とは一致しません。提案への賛成ではなく、コーヒーから紅茶への変更が見えます。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"I ordered tea instead.","jp":"代わりに紅茶を注文しました。"},{"id":"b","en":"I’d like a coffee, please.","jp":"コーヒーをお願いします。"},{"id":"c","en":"What did you order?","jp":"何を注文しましたか？"},{"id":"d","en":"That sounds good.","jp":"それはよさそうですね。"}],"correct":"a","image":"/assets/questions/visual/june-28-04-tea-instead.webp","imageAlt":"A café customer chooses tea instead of coffee.","visualAssetId":"june-28-04"}'::jsonb, false, 1),
      ('june-28', 'june-28-extra-visual-5', 42, 'See It', 'situation', '{"id":"june-28-extra-visual-5","format":"situation","type":"situation","section":"See It","topic":"restaurants","isOriginal":false,"hint":"Notice who is speaking and the extra items offered after the meal.","hintJa":"食後に誰が話し、追加で何を勧めているかに注目しましょう。","explanation":"“Would you like anything else?” is correct. After the meal, the server presents extra drink and dessert choices to the diner. “How about you?” does not fit because the server is offering more food or drink, not returning a personal question to the diner. “Could I have the menu?” does not fit because the server already has options in hand; the diner is not requesting a menu. “I ordered tea instead.” does not fit because no customer is changing an order to tea; several extra choices are being offered.","explanationJa":"正解は「Would you like anything else?」（ほかに何かいかがですか？）です。食後、店員が客に追加の飲み物やデザートを勧めています。 「How about you?」はこの場面とは一致しません。相手にも同じ質問を返しているのではなく、追加の飲食物を勧めています。 「Could I have the menu?」はこの場面とは一致しません。店員がすでに選択肢を示しており、客がメニューを求めてはいません。 「I ordered tea instead.」はこの場面とは一致しません。客が紅茶へ注文変更しているのではなく、複数の追加品が提示されています。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"Would you like anything else?","jp":"ほかに何かいかがですか？"},{"id":"b","en":"How about you?","jp":"あなたはどうですか？"},{"id":"c","en":"Could I have the menu?","jp":"メニューをいただけますか？"},{"id":"d","en":"I ordered tea instead.","jp":"代わりに紅茶を注文しました。"}],"correct":"a","image":"/assets/questions/visual/june-28-05-anything-else.webp","imageAlt":"A server offers a diner an additional drink or dessert after the meal.","visualAssetId":"june-28-05"}'::jsonb, false, 1),
      ('june-29', 'june-29-extra-visual-1', 32, 'See It', 'situation', '{"id":"june-29-extra-visual-1","format":"situation","type":"situation","section":"See It","topic":"hear","isOriginal":false,"hint":"Look at the restaurant image on the phone and the other person’s recognition reaction.","hintJa":"スマートフォンのレストラン画像と、それを見た相手の思い出した表情を見ましょう。","explanation":"“I’ve heard of that restaurant.” is correct. A friend shows a restaurant, and the other person recognizes its name or reputation. “I heard it clearly.” does not fit because the reaction is recognition of a restaurant, not confirmation that a sound was audible. “For real?” does not fit because the person looks knowingly familiar with the restaurant rather than surprised or doubtful. “Click the top-right box.” does not fit because the phone displays a restaurant image, not a grid with a top-right cell.","explanationJa":"正解は「I’ve heard of that restaurant.」（そのレストランの名前は聞いたことがあります。）です。友人がレストランを見せると、相手はその店を知っている反応をしています。 「I heard it clearly.」はこの場面とは一致しません。音が明瞭に聞こえた確認ではなく、レストランを知っている反応です。 「For real?」はこの場面とは一致しません。驚いて疑っているのではなく、店を知っている様子です。 「Click the top-right box.」はこの場面とは一致しません。画面はレストラン画像で、右上のマスを押す操作ではありません。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"I’ve heard of that restaurant.","jp":"そのレストランの名前は聞いたことがあります。"},{"id":"b","en":"I heard it clearly.","jp":"それがはっきり聞こえました。"},{"id":"c","en":"For real?","jp":"本当に？"},{"id":"d","en":"Click the top-right box.","jp":"右上のマスを押してください。"}],"correct":"a","image":"/assets/questions/visual/june-29-01-heard-of-restaurant.webp","imageAlt":"A person recognizes a restaurant shown by a friend.","visualAssetId":"june-29-01"}'::jsonb, false, 1),
      ('june-29', 'june-29-extra-visual-2', 33, 'See It', 'situation', '{"id":"june-29-extra-visual-2","format":"situation","type":"situation","section":"See It","topic":"hear","isOriginal":false,"hint":"Follow the clean sound waves reaching both headphones and the listener’s confident response.","hintJa":"両耳のヘッドホンに届く明瞭な音の波と、聞き手の確信した反応を見ましょう。","explanation":"“I heard it clearly.” is correct. Clear sound reaches both ears, and the listener confirms that the announcement was audible. “I heard about it yesterday.” does not fit because the image shows listening now, with no evidence of learning news yesterday. “For real?” does not fit because the listener is confirming clear reception, not reacting with disbelief. “I didn’t hear what she said.” does not fit because the sound waves reach the listener cleanly and the expression shows understanding, not failure to hear.","explanationJa":"正解は「I heard it clearly.」（それがはっきり聞こえました。）です。明瞭な音が両耳に届き、聞き手は放送を聞き取れたと示しています。 「I heard about it yesterday.」はこの場面とは一致しません。今まさに聞いている場面で、昨日その話を知った証拠はありません。 「For real?」はこの場面とは一致しません。疑って驚いているのではなく、音を明瞭に受け取れたと確認しています。 「I didn’t hear what she said.」はこの場面とは一致しません。音は明瞭に届き、聞き手も理解した表情なので、聞き取れなかった場面ではありません。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"I heard it clearly.","jp":"それがはっきり聞こえました。"},{"id":"b","en":"I heard about it yesterday.","jp":"昨日そのことについて聞きました。"},{"id":"c","en":"For real?","jp":"本当に？"},{"id":"d","en":"I didn’t hear what she said.","jp":"彼女が言ったことが聞こえませんでした。"}],"correct":"a","image":"/assets/questions/visual/june-29-02-heard-clearly.webp","imageAlt":"A listener hears an announcement clearly through headphones.","visualAssetId":"june-29-02"}'::jsonb, false, 1),
      ('june-29', 'june-29-extra-visual-3', 34, 'See It', 'situation', '{"id":"june-29-extra-visual-3","format":"situation","type":"situation","section":"See It","topic":"position","isOriginal":false,"hint":"Check the exact corner of the grid touched by the finger.","hintJa":"指が触れているマスが、グリッドのどの角にあるか確認しましょう。","explanation":"“Click the top-right box.” is correct. The finger is pressing the cell at the upper-right corner of the grid. “I heard it clearly.” does not fit because the image shows a touch-screen position, with no listening action or sound. “The button is in the bottom-left corner.” does not fit because the selected cell is upper-right, the opposite corner from bottom-left. “I didn’t hear what she said.” does not fit because no speaker or failed listening is pictured; a grid cell is being selected.","explanationJa":"正解は「Click the top-right box.」（右上のマスを押してください。）です。指はグリッドの右上にあるマスを押しています。 「I heard it clearly.」はこの場面とは一致しません。聞き取りや音ではなく、画面上の位置を押す操作です。 「The button is in the bottom-left corner.」はこの場面とは一致しません。選ばれているのは右上で、左下とは反対の角です。 「I didn’t hear what she said.」はこの場面とは一致しません。話し手や聞き取り失敗はなく、グリッドのマスを選んでいます。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"Click the top-right box.","jp":"右上のマスを押してください。"},{"id":"b","en":"I heard it clearly.","jp":"それがはっきり聞こえました。"},{"id":"c","en":"The button is in the bottom-left corner.","jp":"ボタンは左下にあります。"},{"id":"d","en":"I didn’t hear what she said.","jp":"彼女が言ったことが聞こえませんでした。"}],"correct":"a","image":"/assets/questions/visual/june-29-03-top-right-box.webp","imageAlt":"A finger selects the top-right cell of a simple grid.","visualAssetId":"june-29-03"}'::jsonb, false, 1),
      ('june-29', 'june-29-extra-visual-4', 35, 'See It', 'situation', '{"id":"june-29-extra-visual-4","format":"situation","type":"situation","section":"See It","topic":"position","isOriginal":false,"hint":"Identify the one corner containing the round button.","hintJa":"丸いボタンが置かれている角を特定しましょう。","explanation":"“The button is in the bottom-left corner.” is correct. The only button appears in the lower-left corner of the screen. “I’ve heard of that restaurant.” does not fit because the screen is a simple layout, not a restaurant being recognized. “Click the top-right box.” does not fit because the visible control is bottom-left, not a box at the top-right. “I didn’t hear what she said.” does not fit because the visual concerns a button’s location, not difficulty hearing a woman.","explanationJa":"正解は「The button is in the bottom-left corner.」（ボタンは左下にあります。）です。画面上の唯一のボタンは左下の角にあります。 「I’ve heard of that restaurant.」はこの場面とは一致しません。画面は単純な配置図で、レストランを知っている場面ではありません。 「Click the top-right box.」はこの場面とは一致しません。見えている操作対象は左下で、右上のマスではありません。 「I didn’t hear what she said.」はこの場面とは一致しません。女性の声を聞き取れない場面ではなく、ボタンの位置を示しています。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"The button is in the bottom-left corner.","jp":"ボタンは左下にあります。"},{"id":"b","en":"I’ve heard of that restaurant.","jp":"そのレストランの名前は聞いたことがあります。"},{"id":"c","en":"Click the top-right box.","jp":"右上のマスを押してください。"},{"id":"d","en":"I didn’t hear what she said.","jp":"彼女が言ったことが聞こえませんでした。"}],"correct":"a","image":"/assets/questions/visual/june-29-04-bottom-left-button.webp","imageAlt":"A button is clearly located in the bottom-left corner of a screen.","visualAssetId":"june-29-04"}'::jsonb, false, 1),
      ('june-29', 'june-29-extra-visual-5', 36, 'See It', 'situation', '{"id":"june-29-extra-visual-5","format":"situation","type":"situation","section":"See It","topic":"hear","isOriginal":false,"hint":"Compare the woman speaking with the noise that interrupts what reaches the listener.","hintJa":"女性が話す様子と、聞き手に届く声を妨げる周囲の騒音を比べましょう。","explanation":"“I didn’t hear what she said.” is correct. Crowd and train noise block the woman’s words, and the listener cups an ear in confusion. “I’ve heard of that restaurant.” does not fit because no restaurant is being recognized; the problem is inaudible speech in a noisy station. “I heard it clearly.” does not fit because noise visibly interrupts the speech and the listener looks confused, so the message was not clear. “For real?” does not fit because the hand-to-ear gesture signals a hearing problem, not disbelief about surprising news.","explanationJa":"正解は「I didn’t hear what she said.」（彼女が言ったことが聞こえませんでした。）です。人混みと列車の騒音が女性の言葉を遮り、聞き手は困って耳に手を当てています。 「I’ve heard of that restaurant.」はこの場面とは一致しません。レストランを知っている場面ではなく、騒がしい駅で声が聞こえない状況です。 「I heard it clearly.」はこの場面とは一致しません。騒音が声を遮り、聞き手も困っているため、明瞭に聞こえた場面ではありません。 「For real?」はこの場面とは一致しません。耳に手を当てる動作は聞き取りの問題で、驚く話を疑う反応ではありません。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"I didn’t hear what she said.","jp":"彼女が言ったことが聞こえませんでした。"},{"id":"b","en":"I’ve heard of that restaurant.","jp":"そのレストランの名前は聞いたことがあります。"},{"id":"c","en":"I heard it clearly.","jp":"それがはっきり聞こえました。"},{"id":"d","en":"For real?","jp":"本当に？"}],"correct":"a","image":"/assets/questions/visual/june-29-05-could-not-hear.webp","imageAlt":"A listener cannot hear a woman speaking because of loud background noise.","visualAssetId":"june-29-05"}'::jsonb, false, 1),
      ('june-30', 'june-30-extra-visual-1', 39, 'See It', 'situation', '{"id":"june-30-extra-visual-1","format":"situation","type":"situation","section":"See It","topic":"feelings","isOriginal":false,"hint":"Use the construction sound waves and the person’s facial expression as the main clues.","hintJa":"工事の音の波と、人物の表情を主な手掛かりにしましょう。","explanation":"“I’m annoyed by the noise.” is correct. Loud construction reaches the room, and the person covers an ear with an irritated expression. “I prefer tea because it’s lighter.” does not fit because there are no drinks or taste comparison; the person is reacting to construction noise. “This exercise is easier than the last one.” does not fit because no exercises are being compared; the visible source of discomfort is noise. “They scored in the first half.” does not fit because no football match or goal appears in the apartment scene.","explanationJa":"正解は「I’m annoyed by the noise.」（その音にイライラしています。）です。大きな工事音が部屋まで届き、人物は苛立った表情で耳をふさいでいます。 「I prefer tea because it’s lighter.」はこの場面とは一致しません。飲み物や味の比較はなく、人物は工事音に反応しています。 「This exercise is easier than the last one.」はこの場面とは一致しません。練習問題を比較しておらず、不快感の原因は見えている騒音です。 「They scored in the first half.」はこの場面とは一致しません。室内の場面にサッカーの試合や得点はありません。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"I’m annoyed by the noise.","jp":"その音にイライラしています。"},{"id":"b","en":"I prefer tea because it’s lighter.","jp":"軽い味なので紅茶の方が好きです。"},{"id":"c","en":"This exercise is easier than the last one.","jp":"この練習は前のものより簡単です。"},{"id":"d","en":"They scored in the first half.","jp":"前半に得点しました。"}],"correct":"a","image":"/assets/questions/visual/june-30-01-annoyed-by-noise.webp","imageAlt":"A person looks annoyed by loud construction noise outside.","visualAssetId":"june-30-01"}'::jsonb, false, 1),
      ('june-30', 'june-30-extra-visual-2', 40, 'See It', 'situation', '{"id":"june-30-extra-visual-2","format":"situation","type":"situation","section":"See It","topic":"preferences","isOriginal":false,"hint":"Compare the pale drink being chosen with the darker drink set aside.","hintJa":"選ばれた淡い色の飲み物と、脇に置かれた濃い色の飲み物を比べましょう。","explanation":"“I prefer tea because it’s lighter.” is correct. The person chooses the pale tea and rejects the darker coffee because of the lighter quality. “I’m annoyed by the noise.” does not fit because the person looks pleased with a drink choice; no noise source is shown. “This exercise is easier than the last one.” does not fit because the image compares beverages, not two learning exercises. “They scored in the first half.” does not fit because there is no sport, scoreboard, or goal in the café scene.","explanationJa":"正解は「I prefer tea because it’s lighter.」（軽い味なので紅茶の方が好きです。）です。人物は軽い味を示す淡い紅茶を選び、濃いコーヒーをよけています。 「I’m annoyed by the noise.」はこの場面とは一致しません。人物は飲み物の選択に満足しており、騒音源は描かれていません。 「This exercise is easier than the last one.」はこの場面とは一致しません。比較しているのは飲み物で、二つの練習問題ではありません。 「They scored in the first half.」はこの場面とは一致しません。カフェの場面に競技・得点表示・ゴールはありません。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"I prefer tea because it’s lighter.","jp":"軽い味なので紅茶の方が好きです。"},{"id":"b","en":"I’m annoyed by the noise.","jp":"その音にイライラしています。"},{"id":"c","en":"This exercise is easier than the last one.","jp":"この練習は前のものより簡単です。"},{"id":"d","en":"They scored in the first half.","jp":"前半に得点しました。"}],"correct":"a","image":"/assets/questions/visual/june-30-02-prefers-light-tea.webp","imageAlt":"A person chooses light tea instead of a darker coffee.","visualAssetId":"june-30-02"}'::jsonb, false, 1),
      ('june-30', 'june-30-extra-visual-3', 41, 'See It', 'situation', '{"id":"june-30-extra-visual-3","format":"situation","type":"situation","section":"See It","topic":"sports","isOriginal":false,"hint":"Read the match clock and notice when the ball enters the goal.","hintJa":"試合時計を確認し、ボールがいつゴールに入ったかを見ましょう。","explanation":"“They scored in the first half.” is correct. The ball enters the goal while the clock still shows a time before halftime. “I prefer tea because it’s lighter.” does not fit because the visual is a football goal, not a comparison between tea and coffee. “Who do you think will win?” does not fit because the image records an actual early goal, not a conversation asking for a prediction. “The second half was exciting.” does not fit because the clock places this goal before halftime, not in the second half.","explanationJa":"正解は「They scored in the first half.」（前半に得点しました。）です。ハーフタイム前の時刻を示す時計のもとで、ボールがゴールに入っています。 「I prefer tea because it’s lighter.」はこの場面とは一致しません。紅茶とコーヒーの比較ではなく、サッカーの得点場面です。 「Who do you think will win?」はこの場面とは一致しません。勝敗予想を尋ねる会話ではなく、実際の前半の得点を示しています。 「The second half was exciting.」はこの場面とは一致しません。時計はハーフタイム前を示しており、後半の場面ではありません。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"They scored in the first half.","jp":"前半に得点しました。"},{"id":"b","en":"I prefer tea because it’s lighter.","jp":"軽い味なので紅茶の方が好きです。"},{"id":"c","en":"Who do you think will win?","jp":"誰が勝つと思いますか？"},{"id":"d","en":"The second half was exciting.","jp":"後半はわくわくしました。"}],"correct":"a","image":"/assets/questions/visual/june-30-03-first-half-goal.webp","imageAlt":"A football team scores before the halftime break.","visualAssetId":"june-30-03"}'::jsonb, false, 1),
      ('june-30', 'june-30-extra-visual-4', 42, 'See It', 'situation', '{"id":"june-30-extra-visual-4","format":"situation","type":"situation","section":"See It","topic":"sports","isOriginal":false,"hint":"Use the late match clock and the crowd’s energetic reaction together.","hintJa":"試合後半の時計と、観客の熱狂した反応を合わせて考えましょう。","explanation":"“The second half was exciting.” is correct. The clock shows the match well past halftime, and the close action excites the fans. “I’m annoyed by the noise.” does not fit because the crowd is cheering with excitement, not covering their ears in irritation. “This exercise is easier than the last one.” does not fit because a live football match is shown, with no comparison of exercises. “They scored in the first half.” does not fit because the visible clock is after halftime, so it cannot support a first-half statement.","explanationJa":"正解は「The second half was exciting.」（後半はわくわくしました。）です。時計はハーフタイム後を示し、接戦の展開に観客が興奮しています。 「I’m annoyed by the noise.」はこの場面とは一致しません。観客は騒音に苛立って耳をふさぐのではなく、興奮して応援しています。 「This exercise is easier than the last one.」はこの場面とは一致しません。映っているのは試合で、練習問題の難易度比較ではありません。 「They scored in the first half.」はこの場面とは一致しません。見える時計はハーフタイム後なので、前半の得点を表していません。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"The second half was exciting.","jp":"後半はわくわくしました。"},{"id":"b","en":"I’m annoyed by the noise.","jp":"その音にイライラしています。"},{"id":"c","en":"This exercise is easier than the last one.","jp":"この練習は前のものより簡単です。"},{"id":"d","en":"They scored in the first half.","jp":"前半に得点しました。"}],"correct":"a","image":"/assets/questions/visual/june-30-04-exciting-second-half.webp","imageAlt":"Fans react excitedly during the second half of a close football match.","visualAssetId":"june-30-04"}'::jsonb, false, 1),
      ('june-30', 'june-30-extra-visual-5', 43, 'See It', 'situation', '{"id":"june-30-extra-visual-5","format":"situation","type":"situation","section":"See It","topic":"feelings","isOriginal":false,"hint":"Count the different devices failing and notice the user’s overall reaction.","hintJa":"動かない機器がいくつあるかと、利用者の全体的な反応を見ましょう。","explanation":"“I was frustrated because nothing worked.” is correct. The laptop, printer, and phone all fail, leaving the person visibly frustrated. “I’m annoyed by the noise.” does not fit because the problem is several broken devices, not an audible noise source. “The noise is annoying.” does not fit because no sound waves or noisy activity appear; the screens and printer show failures. “This exercise is easier than the last one.” does not fit because nothing is being compared for difficulty; every attempted device is failing.","explanationJa":"正解は「I was frustrated because nothing worked.」（何もうまくいかず、もどかしかったです。）です。パソコン・プリンター・電話がすべて動かず、人物は強くもどかしさを感じています。 「I’m annoyed by the noise.」はこの場面とは一致しません。問題は複数の機器の故障で、騒音源ではありません。 「The noise is annoying.」はこの場面とは一致しません。音の波や騒がしい活動はなく、画面とプリンターの不具合が見えます。 「This exercise is easier than the last one.」はこの場面とは一致しません。難易度の比較ではなく、試した機器がすべて失敗しています。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"I was frustrated because nothing worked.","jp":"何もうまくいかず、もどかしかったです。"},{"id":"b","en":"I’m annoyed by the noise.","jp":"その音にイライラしています。"},{"id":"c","en":"The noise is annoying.","jp":"その音はイライラさせます。"},{"id":"d","en":"This exercise is easier than the last one.","jp":"この練習は前のものより簡単です。"}],"correct":"a","image":"/assets/questions/visual/june-30-05-nothing-worked.webp","imageAlt":"A frustrated person faces several devices that are not working.","visualAssetId":"june-30-05"}'::jsonb, false, 1),
      ('july-07', 'july-07-draft-visual-1', 26, 'See It', 'situation', '{"id":"july-07-draft-visual-1","format":"situation","type":"situation","section":"See It","topic":"bring","isOriginal":false,"hint":"Focus on the notebook already in the learner’s hands upon arrival.","hintJa":"学習者が到着した時点ですでに手に持っているノートを見ましょう。","explanation":"“I brought my notebook.” is correct. The learner arrives at class carrying the notebook from another place. “I bought a new notebook.” does not fit because no purchase, shop, or new price tag is visible; the notebook is simply being carried in. “Where will she come from?” does not fit because the pictured learner has already arrived, and no question about another woman’s origin is shown. “Could you do it for me?” does not fit because the learner performs the action personally; no task is delegated to someone else.","explanationJa":"正解は「I brought my notebook.」（ノートを持ってきました。）です。学習者は別の場所からノートを持って教室に到着しています。 「I bought a new notebook.」はこの場面とは一致しません。購入・店・値札はなく、ノートを持参しているだけです。 「Where will she come from?」はこの場面とは一致しません。学習者はすでに到着しており、別の女性の出発地を尋ねていません。 「Could you do it for me?」はこの場面とは一致しません。本人が行動しており、他人に作業を依頼していません。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"I brought my notebook.","jp":"ノートを持ってきました。"},{"id":"b","en":"I bought a new notebook.","jp":"新しいノートを買いました。"},{"id":"c","en":"Where will she come from?","jp":"彼女はどこから来ますか？"},{"id":"d","en":"Could you do it for me?","jp":"私のためにしてもらえますか？"}],"correct":"a","image":"/assets/questions/visual/july-07-01-brought-notebook.webp","imageAlt":"A learner arrives in a classroom holding the notebook they brought.","visualAssetId":"july-07-01"}'::jsonb, false, 1),
      ('july-07', 'july-07-draft-visual-2', 27, 'See It', 'situation', '{"id":"july-07-draft-visual-2","format":"situation","type":"situation","section":"See It","topic":"buy","isOriginal":false,"hint":"Look for the stationery-shop exchange and the clearly new item received by the shopper.","hintJa":"文房具店でのやり取りと、買い物客が受け取る新品を見ましょう。","explanation":"“I bought a new notebook.” is correct. At the shop, the customer pays for and receives a new notebook. “You told me to do so.” does not fit because no instruction from another person motivates the scene; a purchase is taking place. “I got a flat tire.” does not fit because there is no vehicle or damaged tire in the stationery shop. “He attended instead of me.” does not fit because no event attendance or substitute person appears; the shopper personally buys an item.","explanationJa":"正解は「I bought a new notebook.」（新しいノートを買いました。）です。店で客が代金を払い、新しいノートを受け取っています。 「You told me to do so.」はこの場面とは一致しません。他人の指示に従う場面ではなく、商品を購入しています。 「I got a flat tire.」はこの場面とは一致しません。文房具店に車やパンクしたタイヤはありません。 「He attended instead of me.」はこの場面とは一致しません。行事への代理出席ではなく、買い物客本人が商品を買っています。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"I bought a new notebook.","jp":"新しいノートを買いました。"},{"id":"b","en":"You told me to do so.","jp":"あなたは私にそうするよう言いました。"},{"id":"c","en":"I got a flat tire.","jp":"タイヤがパンクしました。"},{"id":"d","en":"He attended instead of me.","jp":"彼が私の代わりに出席しました。"}],"correct":"a","image":"/assets/questions/visual/july-07-02-bought-notebook.webp","imageAlt":"A shopper buys a new notebook at a stationery shop.","visualAssetId":"july-07-02"}'::jsonb, false, 1),
      ('july-07', 'july-07-draft-visual-3', 28, 'See It', 'situation', '{"id":"july-07-draft-visual-3","format":"situation","type":"situation","section":"See It","topic":"daily life","isOriginal":false,"hint":"Check the empty battery symbol and the commuter’s worried attempt to use the phone.","hintJa":"空のバッテリー表示と、電話を使おうとして困る通勤者を確認しましょう。","explanation":"“My phone died.” is correct. The phone shows no battery power and will not operate when the commuter needs it. “Where will she come from?” does not fit because no woman’s travel origin is being discussed; the issue is a powerless phone. “She signed it on my behalf.” does not fit because no document, signature, or representative is pictured. “Please bring it tomorrow.” does not fit because the commuter is not requesting a future delivery; the phone has stopped working now.","explanationJa":"正解は「My phone died.」（携帯の充電が切れました。）です。電話のバッテリーは空で、通勤者が必要な時に動かなくなっています。 「Where will she come from?」はこの場面とは一致しません。女性の出発地の話ではなく、電話の電池切れが問題です。 「She signed it on my behalf.」はこの場面とは一致しません。書類・署名・代理人は描かれていません。 「Please bring it tomorrow.」はこの場面とは一致しません。明日持参する依頼ではなく、今電話が動かない状態です。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"My phone died.","jp":"携帯の充電が切れました。"},{"id":"b","en":"Where will she come from?","jp":"彼女はどこから来ますか？"},{"id":"c","en":"She signed it on my behalf.","jp":"彼女が私の代理で署名しました。"},{"id":"d","en":"Please bring it tomorrow.","jp":"明日それを持ってきてください。"}],"correct":"a","image":"/assets/questions/visual/july-07-03-phone-died.webp","imageAlt":"A commuter looks worried at a phone with an empty battery.","visualAssetId":"july-07-03"}'::jsonb, false, 1),
      ('july-07', 'july-07-draft-visual-4', 29, 'See It', 'situation', '{"id":"july-07-draft-visual-4","format":"situation","type":"situation","section":"See It","topic":"travel","isOriginal":false,"hint":"Inspect the wheel beside the stopped car and the driver’s reaction.","hintJa":"止まった車の横にあるタイヤと、運転手の反応を見ましょう。","explanation":"“I got a flat tire.” is correct. The driver finds a visibly deflated tire on the parked car. “I’m good at cooking.” does not fit because no kitchen or cooking skill is shown; the problem is with a car wheel. “He attended instead of me.” does not fit because no meeting or substitute attendee appears at the roadside. “I bought a new notebook.” does not fit because there is no stationery purchase; the driver is examining a damaged tire.","explanationJa":"正解は「I got a flat tire.」（タイヤがパンクしました。）です。運転手は停車した車のタイヤが明らかにしぼんでいるのを発見しています。 「I’m good at cooking.」はこの場面とは一致しません。台所や料理の能力ではなく、車輪の問題が描かれています。 「He attended instead of me.」はこの場面とは一致しません。道路脇の場面に会議や代理出席者はありません。 「I bought a new notebook.」はこの場面とは一致しません。文房具の購入ではなく、運転手が傷んだタイヤを調べています。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"I got a flat tire.","jp":"タイヤがパンクしました。"},{"id":"b","en":"I’m good at cooking.","jp":"料理が得意です。"},{"id":"c","en":"He attended instead of me.","jp":"彼が私の代わりに出席しました。"},{"id":"d","en":"I bought a new notebook.","jp":"新しいノートを買いました。"}],"correct":"a","image":"/assets/questions/visual/july-07-04-flat-tire.webp","imageAlt":"A driver discovers a flat tire beside a parked car.","visualAssetId":"july-07-04"}'::jsonb, false, 1),
      ('july-07', 'july-07-draft-visual-5', 30, 'See It', 'situation', '{"id":"july-07-draft-visual-5","format":"situation","type":"situation","section":"See It","topic":"behalf","isOriginal":false,"hint":"Notice whose document it is and who is authorized to write the signature.","hintJa":"書類が誰のもので、誰が権限を得て署名しているかに注目しましょう。","explanation":"“She signed it on my behalf.” is correct. The woman signs a colleague’s document with clear authorization to represent that person. “Could you do it for me?” does not fit because the image shows the authorized action already being completed, not the original request for help. “Please bring it tomorrow.” does not fit because nothing is scheduled for delivery tomorrow; the document is being signed now. “My phone died.” does not fit because no phone or empty battery is visible; the central object is a signed document.","explanationJa":"正解は「She signed it on my behalf.」（彼女が私の代理で署名しました。）です。女性は同僚の代理権を得て、その人の書類に署名しています。 「Could you do it for me?」はこの場面とは一致しません。助けを依頼する段階ではなく、権限を得た行為が実際に行われています。 「Please bring it tomorrow.」はこの場面とは一致しません。明日の持参予定ではなく、今その場で書類に署名しています。 「My phone died.」はこの場面とは一致しません。電話や電池切れはなく、中心にあるのは署名する書類です。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"She signed it on my behalf.","jp":"彼女が私の代理で署名しました。"},{"id":"b","en":"Could you do it for me?","jp":"私のためにしてもらえますか？"},{"id":"c","en":"Please bring it tomorrow.","jp":"明日それを持ってきてください。"},{"id":"d","en":"My phone died.","jp":"携帯の充電が切れました。"}],"correct":"a","image":"/assets/questions/visual/july-07-05-on-my-behalf.webp","imageAlt":"A woman signs a document as an authorized representative for a colleague.","visualAssetId":"july-07-05"}'::jsonb, false, 1),
      ('july-11', 'july-11-draft-visual-1', 26, 'See It', 'situation', '{"id":"july-11-draft-visual-1","format":"situation","type":"situation","section":"See It","topic":"connected","isOriginal":false,"hint":"Follow the successful link between the phone and the home wireless router.","hintJa":"スマートフォンと家庭用無線ルーターの間に成立した接続を見ましょう。","explanation":"“My phone is connected to the Wi-Fi.” is correct. A stable wireless link joins the phone to the home router, and the connection indicator is successful. “I connected the cable.” does not fit because the link is wireless and no cable is being attached. “I went back to my hometown.” does not fit because the scene is about a device network at home, not travel to a hometown. “People sometimes stand close when they talk.” does not fit because no face-to-face conversation or interpersonal distance is shown.","explanationJa":"正解は「My phone is connected to the Wi-Fi.」（携帯はWi-Fiにつながっています。）です。スマートフォンと家庭のルーターが安定した無線表示で接続されています。 「I connected the cable.」はこの場面とは一致しません。接続は無線で、ケーブルは取り付けられていません。 「I went back to my hometown.」はこの場面とは一致しません。故郷への移動ではなく、家庭内の機器接続です。 「People sometimes stand close when they talk.」はこの場面とは一致しません。対面会話や人同士の距離は描かれていません。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"My phone is connected to the Wi-Fi.","jp":"携帯はWi-Fiにつながっています。"},{"id":"b","en":"I connected the cable.","jp":"ケーブルを接続しました。"},{"id":"c","en":"I went back to my hometown.","jp":"地元に帰りました。"},{"id":"d","en":"People sometimes stand close when they talk.","jp":"人は話す時に近くに立つことがあります。"}],"correct":"a","image":"/assets/questions/visual/july-11-01-wifi-connected.webp","imageAlt":"A phone is successfully connected to home Wi-Fi.","visualAssetId":"july-11-01"}'::jsonb, false, 1),
      ('july-11', 'july-11-draft-visual-2', 27, 'See It', 'situation', '{"id":"july-11-draft-visual-2","format":"situation","type":"situation","section":"See It","topic":"broadcast","isOriginal":false,"hint":"Use the studio camera, presenter, and real-time broadcast indicators.","hintJa":"スタジオのカメラ、司会者、リアルタイム配信の表示を手掛かりにしましょう。","explanation":"“The program is broadcast live.” is correct. A presenter speaks in a television studio while cameras transmit the program in real time. “We watched the live stream.” does not fit because the image shows production and transmission, not viewers watching a stream. “I noticed a strange sound.” does not fit because no unexpected noise draws attention; the presenter is intentionally on camera. “Is the meeting being streamed live?” does not fit because this is clearly a television program already broadcasting, not a question about a meeting.","explanationJa":"正解は「The program is broadcast live.」（その番組は生放送されます。）です。テレビスタジオで司会者が話し、カメラが番組をリアルタイムで送っています。 「We watched the live stream.」はこの場面とは一致しません。視聴者が配信を見る場面ではなく、番組を制作して送信しています。 「I noticed a strange sound.」はこの場面とは一致しません。不審な音に気づく場面ではなく、司会者が意図的に撮影されています。 「Is the meeting being streamed live?」はこの場面とは一致しません。会議の配信を尋ねているのではなく、テレビ番組が実際に放送されています。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"The program is broadcast live.","jp":"その番組は生放送されます。"},{"id":"b","en":"We watched the live stream.","jp":"ライブ配信を見ました。"},{"id":"c","en":"I noticed a strange sound.","jp":"変な音に気づきました。"},{"id":"d","en":"Is the meeting being streamed live?","jp":"会議はライブ配信されていますか？"}],"correct":"a","image":"/assets/questions/visual/july-11-02-live-broadcast.webp","imageAlt":"A television presenter appears in a live broadcast studio.","visualAssetId":"july-11-02"}'::jsonb, false, 1),
      ('july-11', 'july-11-draft-visual-3', 28, 'See It', 'situation', '{"id":"july-11-draft-visual-3","format":"situation","type":"situation","section":"See It","topic":"hometown","isOriginal":false,"hint":"Notice the traveler arriving at a familiar family home and greeting relatives.","hintJa":"旅行者が親しみのある実家に到着し、家族と再会する様子を見ましょう。","explanation":"“I went back to my hometown.” is correct. With luggage in hand, the traveler returns to the family home and is welcomed by relatives. “My phone is connected to the Wi-Fi.” does not fit because no phone or router is shown; the visible action is a homecoming. “The program is broadcast live.” does not fit because there is no studio, camera, or broadcast; family members greet a traveler. “People sometimes stand close when they talk.” does not fit because their closeness comes from a reunion, not a general observation about conversation distance.","explanationJa":"正解は「I went back to my hometown.」（地元に帰りました。）です。荷物を持った旅行者が家族の家へ戻り、親族に迎えられています。 「My phone is connected to the Wi-Fi.」はこの場面とは一致しません。電話やルーターはなく、帰省の場面です。 「The program is broadcast live.」はこの場面とは一致しません。スタジオ・カメラ・放送はなく、家族が旅行者を迎えています。 「People sometimes stand close when they talk.」はこの場面とは一致しません。近さは再会によるもので、会話距離について一般的に述べる場面ではありません。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"I went back to my hometown.","jp":"地元に帰りました。"},{"id":"b","en":"My phone is connected to the Wi-Fi.","jp":"携帯はWi-Fiにつながっています。"},{"id":"c","en":"The program is broadcast live.","jp":"その番組は生放送されます。"},{"id":"d","en":"People sometimes stand close when they talk.","jp":"人は話す時に近くに立つことがあります。"}],"correct":"a","image":"/assets/questions/visual/july-11-03-hometown.webp","imageAlt":"A traveler returns to their hometown and greets family.","visualAssetId":"july-11-03"}'::jsonb, false, 1),
      ('july-11', 'july-11-draft-visual-4', 29, 'See It', 'situation', '{"id":"july-11-draft-visual-4","format":"situation","type":"situation","section":"See It","topic":"notice","isOriginal":false,"hint":"Look at the person’s sudden turn toward the room where the unfamiliar sound begins.","hintJa":"聞き慣れない音がした部屋へ、人物が突然振り向く様子を見ましょう。","explanation":"“I noticed a strange sound.” is correct. An unexpected sound comes from another room, causing the person to stop and turn toward it. “I realized I had the wrong key.” does not fit because there is no locked door or key; attention is drawn by a sound. “Is the meeting being streamed live?” does not fit because no meeting or streaming device appears in the room. “The program is broadcast live.” does not fit because the sound is an unexplained household event, not a planned studio broadcast.","explanationJa":"正解は「I noticed a strange sound.」（変な音に気づきました。）です。別の部屋から予想外の音がし、人物は立ち止まってそちらへ振り向いています。 「I realized I had the wrong key.」はこの場面とは一致しません。鍵や施錠されたドアはなく、音に注意を引かれています。 「Is the meeting being streamed live?」はこの場面とは一致しません。会議や配信用機器は室内にありません。 「The program is broadcast live.」はこの場面とは一致しません。計画されたスタジオ放送ではなく、家の中の原因不明の音です。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"I noticed a strange sound.","jp":"変な音に気づきました。"},{"id":"b","en":"I realized I had the wrong key.","jp":"違う鍵を持っていると気づきました。"},{"id":"c","en":"Is the meeting being streamed live?","jp":"会議はライブ配信されていますか？"},{"id":"d","en":"The program is broadcast live.","jp":"その番組は生放送されます。"}],"correct":"a","image":"/assets/questions/visual/july-11-04-noticed-sound.webp","imageAlt":"A person suddenly notices a strange sound from another room.","visualAssetId":"july-11-04"}'::jsonb, false, 1),
      ('july-11', 'july-11-draft-visual-5', 30, 'See It', 'situation', '{"id":"july-11-draft-visual-5","format":"situation","type":"situation","section":"See It","topic":"realize","isOriginal":false,"hint":"Compare the key in hand with the lock it fails to open and the person’s realization.","hintJa":"手に持つ鍵、開かない錠、間違いに気づいた表情を比べましょう。","explanation":"“I realized I had the wrong key.” is correct. At the locked door, the key does not fit and the person recognizes it is the wrong one. “People sometimes stand close when they talk.” does not fit because only one person and a lock are central; no close conversation occurs. “I didn’t notice the sign.” does not fit because no overlooked sign is shown; the failed key identifies the mistake. “We watched the live stream.” does not fit because there is no screen or stream; the person is stranded at a locked door.","explanationJa":"正解は「I realized I had the wrong key.」（違う鍵を持っていると気づきました。）です。施錠されたドアで鍵が合わず、人物は違う鍵を持ってきたと気づいています。 「People sometimes stand close when they talk.」はこの場面とは一致しません。中心は一人と錠で、近距離の会話はありません。 「I didn’t notice the sign.」はこの場面とは一致しません。見落とした標識はなく、合わない鍵が間違いを示しています。 「We watched the live stream.」はこの場面とは一致しません。画面や配信はなく、人物は施錠されたドアの前にいます。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"I realized I had the wrong key.","jp":"違う鍵を持っていると気づきました。"},{"id":"b","en":"People sometimes stand close when they talk.","jp":"人は話す時に近くに立つことがあります。"},{"id":"c","en":"I didn’t notice the sign.","jp":"その標識に気づきませんでした。"},{"id":"d","en":"We watched the live stream.","jp":"ライブ配信を見ました。"}],"correct":"a","image":"/assets/questions/visual/july-11-05-wrong-key.webp","imageAlt":"A person realizes they brought the wrong key at a locked door.","visualAssetId":"july-11-05"}'::jsonb, false, 1),
      ('july-12', 'july-12-draft-visual-1', 26, 'See It', 'situation', '{"id":"july-12-draft-visual-1","format":"situation","type":"situation","section":"See It","topic":"past","isOriginal":false,"hint":"Use both the midday clock and the meal being eaten.","hintJa":"正午を示す時計と、食べている食事の両方を手掛かりにしましょう。","explanation":"“I had lunch at noon.” is correct. The clock reads noon while the person is eating a midday meal. “I don’t drink alcohol.” does not fit because the visible event is a timed meal, with no alcohol or refusal. “She has already had breakfast.” does not fit because the clock and food place the meal at noon, not breakfast earlier in the day. “He hasn’t had any coffee.” does not fit because the image establishes lunch at noon, not the absence of coffee.","explanationJa":"正解は「I had lunch at noon.」（正午に昼食を食べました。）です。時計が正午を示す時に、人物が昼の食事を取っています。 「I don’t drink alcohol.」はこの場面とは一致しません。時間の分かる食事で、酒や飲酒拒否はありません。 「She has already had breakfast.」はこの場面とは一致しません。時計と食事は正午の昼食を示し、朝食ではありません。 「He hasn’t had any coffee.」はこの場面とは一致しません。示されているのは正午の昼食で、コーヒーを飲んでいないことではありません。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"I had lunch at noon.","jp":"正午に昼食を食べました。"},{"id":"b","en":"I don’t drink alcohol.","jp":"私はお酒を飲みません。"},{"id":"c","en":"She has already had breakfast.","jp":"彼女はもう朝食を食べました。"},{"id":"d","en":"He hasn’t had any coffee.","jp":"彼はまだコーヒーを飲んでいません。"}],"correct":"a","image":"/assets/questions/visual/july-12-01-lunch-noon.webp","imageAlt":"A person eats lunch at noon.","visualAssetId":"july-12-01"}'::jsonb, false, 1),
      ('july-12', 'july-12-draft-visual-2', 27, 'See It', 'situation', '{"id":"july-12-draft-visual-2","format":"situation","type":"situation","section":"See It","topic":"any","isOriginal":false,"hint":"Check the late time, empty lunchbox, and the person’s hunger.","hintJa":"遅い時刻、空の弁当箱、人物の空腹の様子を確認しましょう。","explanation":"“I haven’t eaten anything today.” is correct. Late in the day, the person is hungry and the lunchbox remains empty, showing no food has been eaten. “She has already had breakfast.” does not fit because the hungry person and empty container contradict a completed breakfast. “I’ve had this bag for years.” does not fit because the important container is an empty lunchbox, not an old bag kept for years. “Have you had lunch yet?” does not fit because the image answers the eating status directly rather than showing someone asking a question.","explanationJa":"正解は「I haven’t eaten anything today.」（今日はまだ何も食べていません。）です。一日の遅い時間でも空腹で弁当箱が空のままなので、まだ何も食べていません。 「She has already had breakfast.」はこの場面とは一致しません。空腹の人物と空の容器は、朝食を済ませた状況と合いません。 「I’ve had this bag for years.」はこの場面とは一致しません。重要なのは空の弁当箱で、長年持つかばんではありません。 「Have you had lunch yet?」はこの場面とは一致しません。昼食を尋ねる会話ではなく、食べていない状態そのものを示しています。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"I haven’t eaten anything today.","jp":"今日はまだ何も食べていません。"},{"id":"b","en":"She has already had breakfast.","jp":"彼女はもう朝食を食べました。"},{"id":"c","en":"I’ve had this bag for years.","jp":"この鞄を何年も持っています。"},{"id":"d","en":"Have you had lunch yet?","jp":"もう昼食を食べましたか？"}],"correct":"a","image":"/assets/questions/visual/july-12-02-not-eaten-today.webp","imageAlt":"A hungry person has an empty lunchbox late in the day.","visualAssetId":"july-12-02"}'::jsonb, false, 1),
      ('july-12', 'july-12-draft-visual-3', 28, 'See It', 'situation', '{"id":"july-12-draft-visual-3","format":"situation","type":"situation","section":"See It","topic":"already","isOriginal":false,"hint":"Notice the finished breakfast dishes and the woman’s satisfied expression.","hintJa":"食べ終えた朝食の皿と、女性の満足した表情を見ましょう。","explanation":"“She has already had breakfast.” is correct. The breakfast plate is already empty and the woman looks satisfied after finishing it. “We haven’t decided yet.” does not fit because no group decision is pending; the completed meal is visible. “He hasn’t had any coffee.” does not fit because the subject is a woman with a finished breakfast, not a man lacking coffee. “I had lunch at noon.” does not fit because the meal shown is breakfast and is already finished, not lunch at midday.","explanationJa":"正解は「She has already had breakfast.」（彼女はもう朝食を食べました。）です。朝食の皿はすでに空で、女性は食べ終えて満足しています。 「We haven’t decided yet.」はこの場面とは一致しません。集団での未決定事項ではなく、食事が完了しています。 「He hasn’t had any coffee.」はこの場面とは一致しません。コーヒーを飲んでいない男性ではなく、朝食を終えた女性です。 「I had lunch at noon.」はこの場面とは一致しません。示されているのは昼食ではなく、すでに終えた朝食です。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"She has already had breakfast.","jp":"彼女はもう朝食を食べました。"},{"id":"b","en":"We haven’t decided yet.","jp":"まだ決めていません。"},{"id":"c","en":"He hasn’t had any coffee.","jp":"彼はまだコーヒーを飲んでいません。"},{"id":"d","en":"I had lunch at noon.","jp":"正午に昼食を食べました。"}],"correct":"a","image":"/assets/questions/visual/july-12-03-breakfast-already.webp","imageAlt":"A satisfied woman has already finished breakfast.","visualAssetId":"july-12-03"}'::jsonb, false, 1),
      ('july-12', 'july-12-draft-visual-4', 29, 'See It', 'situation', '{"id":"july-12-draft-visual-4","format":"situation","type":"situation","section":"See It","topic":"continuation","isOriginal":false,"hint":"Follow the same distinctive bag through the sequence of passing years.","hintJa":"年月が進む連続場面で、同じ特徴的なかばんを追いましょう。","explanation":"“I’ve had this bag for years.” is correct. The same worn and well-loved bag remains with its owner across several years. “He hasn’t had any coffee.” does not fit because no man, drink, or missing coffee appears; the evidence is long-term possession. “Have you had lunch yet?” does not fit because no meal question or lunch scene appears in the time sequence. “I haven’t eaten anything today.” does not fit because the repeated bag over years, not food eaten today, is the subject.","explanationJa":"正解は「I’ve had this bag for years.」（この鞄を何年も持っています。）です。使い込まれた同じかばんを、持ち主が何年にもわたって使い続けています。 「He hasn’t had any coffee.」はこの場面とは一致しません。男性や飲み物はなく、長期間の所有が示されています。 「Have you had lunch yet?」はこの場面とは一致しません。年月の流れに昼食の質問や食事場面はありません。 「I haven’t eaten anything today.」はこの場面とは一致しません。今日の食事ではなく、何年も同じかばんを持つことが主題です。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"I’ve had this bag for years.","jp":"この鞄を何年も持っています。"},{"id":"b","en":"He hasn’t had any coffee.","jp":"彼はまだコーヒーを飲んでいません。"},{"id":"c","en":"Have you had lunch yet?","jp":"もう昼食を食べましたか？"},{"id":"d","en":"I haven’t eaten anything today.","jp":"今日はまだ何も食べていません。"}],"correct":"a","image":"/assets/questions/visual/july-12-04-bag-for-years.webp","imageAlt":"The same well-loved bag is used over many years.","visualAssetId":"july-12-04"}'::jsonb, false, 1),
      ('july-12', 'july-12-draft-visual-5', 30, 'See It', 'situation', '{"id":"july-12-draft-visual-5","format":"situation","type":"situation","section":"See It","topic":"past","isOriginal":false,"hint":"Use the evening setting, shared meal, and calendar cue for the previous night.","hintJa":"夜の雰囲気、皆で食べる食事、前夜を示す時間の手掛かりを使いましょう。","explanation":"“They had dinner last night.” is correct. The friends share an evening meal, and the time cue places it on the previous night. “I haven’t had any alcohol yet.” does not fit because the scene shows a completed shared dinner, not one person’s alcohol status. “I don’t drink alcohol.” does not fit because no refusal or general drinking habit is communicated by the dinner scene. “We haven’t decided yet.” does not fit because the event has already happened; no unresolved group choice is pictured.","explanationJa":"正解は「They had dinner last night.」（昨夜夕食を食べました。）です。友人たちが夕食を共にしており、時間の手掛かりから昨夜の出来事だと分かります。 「I haven’t had any alcohol yet.」はこの場面とは一致しません。一人の飲酒状況ではなく、皆で終えた夕食です。 「I don’t drink alcohol.」はこの場面とは一致しません。飲酒拒否や一般的な習慣は、夕食場面から示されません。 「We haven’t decided yet.」はこの場面とは一致しません。出来事はすでに起きており、未解決の集団決定は描かれていません。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"They had dinner last night.","jp":"昨夜夕食を食べました。"},{"id":"b","en":"I haven’t had any alcohol yet.","jp":"まだお酒を飲んでいません。"},{"id":"c","en":"I don’t drink alcohol.","jp":"私はお酒を飲みません。"},{"id":"d","en":"We haven’t decided yet.","jp":"まだ決めていません。"}],"correct":"a","image":"/assets/questions/visual/july-12-05-dinner-last-night.webp","imageAlt":"Friends ate dinner together last night.","visualAssetId":"july-12-05"}'::jsonb, false, 1),
      ('july-13', 'july-13-draft-visual-1', 26, 'See It', 'situation', '{"id":"july-13-draft-visual-1","format":"situation","type":"situation","section":"See It","topic":"possibility","isOriginal":false,"hint":"Use the clock, the waiting posture, and the person’s attention to the silent phone.","hintJa":"時計、待っている姿勢、鳴っていない電話を気にする様子を手掛かりにしましょう。","explanation":"“Someone might call me around this time.” is correct. At the expected time, the person watches the phone and waits for a possible incoming call. “My signal is weak.” does not fit because no weak-signal bars or connection failure appear; the phone is simply being watched. “That’s unusual.” does not fit because the person expects something possible at this time rather than reacting to an abnormal event. “The streets are packed with people.” does not fit because the scene centers on one person and a phone indoors, not a crowded street.","explanationJa":"正解は「Someone might call me around this time.」（この時間帯に誰かが電話するかもしれません。）です。予想される時間になり、人物は電話を見ながら着信の可能性を待っています。 「My signal is weak.」はこの場面とは一致しません。弱い電波表示や接続不良はなく、電話を待って見ています。 「That’s unusual.」はこの場面とは一致しません。異常な出来事に驚くのではなく、この時間に起こり得ることを待っています。 「The streets are packed with people.」はこの場面とは一致しません。人混みの道路ではなく、室内の一人と電話が中心です。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"Someone might call me around this time.","jp":"この時間帯に誰かが電話するかもしれません。"},{"id":"b","en":"My signal is weak.","jp":"電波が弱いです。"},{"id":"c","en":"That’s unusual.","jp":"それは珍しいですね。"},{"id":"d","en":"The streets are packed with people.","jp":"通りは人でいっぱいです。"}],"correct":"a","image":"/assets/questions/visual/july-13-01-expected-call.webp","imageAlt":"A person watches the clock while expecting a possible phone call.","visualAssetId":"july-13-01"}'::jsonb, false, 1),
      ('july-13', 'july-13-draft-visual-2', 27, 'See It', 'situation', '{"id":"july-13-draft-visual-2","format":"situation","type":"situation","section":"See It","topic":"technology","isOriginal":false,"hint":"Count the mobile-signal bars and notice the difficulty using the connection.","hintJa":"携帯電波の本数と、接続を使いにくそうな様子を確認しましょう。","explanation":"“My signal is weak.” is correct. The phone displays very few mobile-signal bars, indicating poor reception. “The Wi-Fi connection is unstable.” does not fit because the display identifies weak mobile reception, not fluctuating Wi-Fi. “This shop doesn’t have tiramisu, but that one does.” does not fit because no shops, desserts, or comparison between locations appears. “Will you be there this time?” does not fit because no meeting place or attendance question is shown; the phone’s reception is the issue.","explanationJa":"正解は「My signal is weak.」（電波が弱いです。）です。電話の携帯電波表示がごく少なく、受信状態の悪さを示しています。 「The Wi-Fi connection is unstable.」はこの場面とは一致しません。表示は不安定なWi-Fiではなく、弱い携帯電波を示しています。 「This shop doesn’t have tiramisu, but that one does.」はこの場面とは一致しません。店・デザート・場所の比較は描かれていません。 「Will you be there this time?」はこの場面とは一致しません。集合場所や出席の質問ではなく、電話の受信状態が問題です。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"My signal is weak.","jp":"電波が弱いです。"},{"id":"b","en":"The Wi-Fi connection is unstable.","jp":"Wi-Fi接続が不安定です。"},{"id":"c","en":"This shop doesn’t have tiramisu, but that one does.","jp":"この店にはティラミスがありませんが、あちらにはあります。"},{"id":"d","en":"Will you be there this time?","jp":"今回はそこにいますか？"}],"correct":"a","image":"/assets/questions/visual/july-13-02-weak-signal.webp","imageAlt":"A phone has a weak mobile signal.","visualAssetId":"july-13-02"}'::jsonb, false, 1),
      ('july-13', 'july-13-draft-visual-3', 28, 'See It', 'situation', '{"id":"july-13-draft-visual-3","format":"situation","type":"situation","section":"See It","topic":"movement","isOriginal":false,"hint":"Follow the runner’s direction and the forgotten item visible inside the office.","hintJa":"走る向きと、オフィス内に見える忘れ物を追いましょう。","explanation":"“I need to rush back.” is correct. After noticing the forgotten document, the person turns and runs quickly back into the office. “That’s unusual.” does not fit because the person is taking urgent corrective action, not merely observing something strange. “The streets are packed with people.” does not fit because the route to the office is not crowded; the focal evidence is one runner returning. “Someone might call me around this time.” does not fit because no expected call or phone is involved; a forgotten office item causes the return.","explanationJa":"正解は「I need to rush back.」（急いで戻る必要があります。）です。忘れた書類に気づき、人物は方向を変えて急いでオフィスへ戻っています。 「That’s unusual.」はこの場面とは一致しません。珍しいと眺めるのではなく、急いで問題を直そうと行動しています。 「The streets are packed with people.」はこの場面とは一致しません。道路の人混みではなく、一人が戻って走ることが中心です。 「Someone might call me around this time.」はこの場面とは一致しません。電話を待っておらず、オフィスの忘れ物が戻る理由です。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"I need to rush back.","jp":"急いで戻る必要があります。"},{"id":"b","en":"That’s unusual.","jp":"それは珍しいですね。"},{"id":"c","en":"The streets are packed with people.","jp":"通りは人でいっぱいです。"},{"id":"d","en":"Someone might call me around this time.","jp":"この時間帯に誰かが電話するかもしれません。"}],"correct":"a","image":"/assets/questions/visual/july-13-03-rush-back.webp","imageAlt":"A person rushes back toward an office after forgetting something.","visualAssetId":"july-13-03"}'::jsonb, false, 1),
      ('july-13', 'july-13-draft-visual-4', 29, 'See It', 'situation', '{"id":"july-13-draft-visual-4","format":"situation","type":"situation","section":"See It","topic":"time","isOriginal":false,"hint":"Track how rapidly the calendar pages move from the start to the end of the week.","hintJa":"週の初めから終わりまで、カレンダーのページがどれほど速く進むか見ましょう。","explanation":"“The week went by quickly.” is correct. Successive calendar pages sweep past rapidly, compressing the whole week into a short visual sequence. “The streets are packed with people.” does not fit because the visual depicts passing calendar time, not dense pedestrian traffic. “There are many people walking in Tokyo.” does not fit because no Tokyo street or walkers appear; calendar pages are the moving elements. “The Wi-Fi connection is unstable.” does not fit because there is no device or network indicator; the changing pages represent time.","explanationJa":"正解は「The week went by quickly.」（一週間が早く過ぎました。）です。連続するカレンダーが急速にめくられ、一週間が短く感じられる流れです。 「The streets are packed with people.」はこの場面とは一致しません。歩行者で混雑した道路ではなく、カレンダー上の時間経過です。 「There are many people walking in Tokyo.」はこの場面とは一致しません。東京の道や歩行者はなく、動いているのはカレンダーです。 「The Wi-Fi connection is unstable.」はこの場面とは一致しません。機器やネットワーク表示はなく、ページの変化は時間を表します。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"The week went by quickly.","jp":"一週間が早く過ぎました。"},{"id":"b","en":"The streets are packed with people.","jp":"通りは人でいっぱいです。"},{"id":"c","en":"There are many people walking in Tokyo.","jp":"東京では多くの人が歩いています。"},{"id":"d","en":"The Wi-Fi connection is unstable.","jp":"Wi-Fi接続が不安定です。"}],"correct":"a","image":"/assets/questions/visual/july-13-04-week-flew-by.webp","imageAlt":"Calendar pages seem to fly past during a quick week.","visualAssetId":"july-13-04"}'::jsonb, false, 1),
      ('july-13', 'july-13-draft-visual-5', 30, 'See It', 'situation', '{"id":"july-13-draft-visual-5","format":"situation","type":"situation","section":"See It","topic":"city","isOriginal":false,"hint":"Look at how little open space remains between pedestrians across the street.","hintJa":"道路全体で歩行者同士の空間がどれほど少ないか見ましょう。","explanation":"“The streets are packed with people.” is correct. Pedestrians fill the street from side to side, leaving almost no open walking space. “It feels long at the beginning of the week.” does not fit because no calendar or subjective passage of time appears; the evidence is crowd density. “Someone might call me around this time.” does not fit because no phone, clock, or waiting caller appears among the crowd. “I need to rush back.” does not fit because no one is turning back toward a destination; many people simply fill the street.","explanationJa":"正解は「The streets are packed with people.」（通りは人でいっぱいです。）です。歩行者が通り一面を埋め、歩ける空間がほとんど残っていません。 「It feels long at the beginning of the week.」はこの場面とは一致しません。カレンダーや時間感覚ではなく、人の密集度が示されています。 「Someone might call me around this time.」はこの場面とは一致しません。人混みの中に電話・時計・着信を待つ人は示されていません。 「I need to rush back.」はこの場面とは一致しません。目的地へ引き返す人物ではなく、多くの人が道路を埋めています。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"The streets are packed with people.","jp":"通りは人でいっぱいです。"},{"id":"b","en":"It feels long at the beginning of the week.","jp":"週の初めは長く感じます。"},{"id":"c","en":"Someone might call me around this time.","jp":"この時間帯に誰かが電話するかもしれません。"},{"id":"d","en":"I need to rush back.","jp":"急いで戻る必要があります。"}],"correct":"a","image":"/assets/questions/visual/july-13-05-packed-street.webp","imageAlt":"A city street is packed with pedestrians.","visualAssetId":"july-13-05"}'::jsonb, false, 1),
      ('july-18', 'july-18-draft-visual-1', 26, 'See It', 'situation', '{"id":"july-18-draft-visual-1","format":"situation","type":"situation","section":"See It","topic":"has","isOriginal":false,"hint":"Identify the animal the woman is holding comfortably in her home.","hintJa":"女性が家で親しそうに抱いている動物を確認しましょう。","explanation":"“She has a cat.” is correct. The woman happily holds her own cat in a familiar home setting. “She doesn’t have a cat.” does not fit because a cat is visibly in her arms, directly contradicting the negative statement. “The pot was on the stove.” does not fit because no kitchen pot or stove appears; the central subject is a pet. “I have a driver’s license.” does not fit because no license, vehicle, or driving context is shown.","explanationJa":"正解は「She has a cat.」（彼女は猫を飼っています。）です。女性は自宅らしい場所で、自分の猫を嬉しそうに抱いています。 「She doesn’t have a cat.」はこの場面とは一致しません。猫を腕に抱いており、猫がいないという否定文と直接矛盾します。 「The pot was on the stove.」はこの場面とは一致しません。鍋やコンロはなく、中心はペットです。 「I have a driver’s license.」はこの場面とは一致しません。免許証・車・運転の場面はありません。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"She has a cat.","jp":"彼女は猫を飼っています。"},{"id":"b","en":"She doesn’t have a cat.","jp":"彼女は猫を飼っていません。"},{"id":"c","en":"The pot was on the stove.","jp":"鍋はコンロにかかっていました。"},{"id":"d","en":"I have a driver’s license.","jp":"運転免許を持っています。"}],"correct":"a","image":"/assets/questions/visual/july-18-01-has-cat.webp","imageAlt":"A woman happily holds her pet cat at home.","visualAssetId":"july-18-01"}'::jsonb, false, 1),
      ('july-18', 'july-18-draft-visual-2', 27, 'See It', 'situation', '{"id":"july-18-draft-visual-2","format":"situation","type":"situation","section":"See It","topic":"stove","isOriginal":false,"hint":"Look at the cookware’s exact position and its safe, unlit condition.","hintJa":"調理器具の正確な位置と、火が出ていない安全な状態を見ましょう。","explanation":"“The pot was on the stove.” is correct. A cooking pot rests normally on top of the stove with no flames or danger. “The pot caught fire.” does not fit because the pot is intact and no flames or smoke are visible. “I have a driver’s license.” does not fit because the image is a kitchen scene without a license or vehicle. “She has a cat.” does not fit because no woman or cat appears; the only focal object is cookware.","explanationJa":"正解は「The pot was on the stove.」（鍋はコンロにかかっていました。）です。調理用の鍋がコンロの上に通常どおり置かれ、炎や危険はありません。 「The pot caught fire.」はこの場面とは一致しません。鍋は無事で、炎や煙は見えません。 「I have a driver’s license.」はこの場面とは一致しません。台所の場面で、免許証や車はありません。 「She has a cat.」はこの場面とは一致しません。女性や猫はおらず、中心の物は調理器具です。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"The pot was on the stove.","jp":"鍋はコンロにかかっていました。"},{"id":"b","en":"The pot caught fire.","jp":"鍋に火がつきました。"},{"id":"c","en":"I have a driver’s license.","jp":"運転免許を持っています。"},{"id":"d","en":"She has a cat.","jp":"彼女は猫を飼っています。"}],"correct":"a","image":"/assets/questions/visual/july-18-02-pot-on-stove.webp","imageAlt":"A cooking pot sits safely on the stove.","visualAssetId":"july-18-02"}'::jsonb, false, 1),
      ('july-18', 'july-18-draft-visual-3', 28, 'See It', 'situation', '{"id":"july-18-draft-visual-3","format":"situation","type":"situation","section":"See It","topic":"fire","isOriginal":false,"hint":"Distinguish the flames on the cookware from a larger fire elsewhere.","hintJa":"調理器具に上がる炎と、建物全体の火災を区別しましょう。","explanation":"“The pot caught fire.” is correct. Flames rise directly from the pot while it sits on the stove. “The house is on fire.” does not fit because the flames are confined to the pot; the building is not burning. “We’re supposed to meet at ten.” does not fit because no clock, appointment, or meeting people appear in the emergency scene. “She doesn’t have a cat.” does not fit because the visual gives no information about a woman or pet ownership.","explanationJa":"正解は「The pot caught fire.」（鍋に火がつきました。）です。コンロ上の鍋そのものから炎が上がっています。 「The house is on fire.」はこの場面とは一致しません。炎は鍋に限られ、建物全体は燃えていません。 「We’re supposed to meet at ten.」はこの場面とは一致しません。時計・約束・待ち合わせる人は火災場面にありません。 「She doesn’t have a cat.」はこの場面とは一致しません。女性やペットの所有について分かるものはありません。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"The pot caught fire.","jp":"鍋に火がつきました。"},{"id":"b","en":"The house is on fire.","jp":"家が燃えています。"},{"id":"c","en":"We’re supposed to meet at ten.","jp":"10時に会うことになっています。"},{"id":"d","en":"She doesn’t have a cat.","jp":"彼女は猫を飼っていません。"}],"correct":"a","image":"/assets/questions/visual/july-18-03-pot-caught-fire.webp","imageAlt":"A cooking pot has caught fire on the stove.","visualAssetId":"july-18-03"}'::jsonb, false, 1),
      ('july-18', 'july-18-draft-visual-4', 29, 'See It', 'situation', '{"id":"july-18-draft-visual-4","format":"situation","type":"situation","section":"See It","topic":"fire","isOriginal":false,"hint":"Use the burning building and firefighters’ response to identify what is literally aflame.","hintJa":"燃えている建物と消防隊の対応から、実際に何が火事なのか判断しましょう。","explanation":"“The house is on fire.” is correct. Flames and smoke come from the house while firefighters work outside it. “He’s on fire today.” does not fit because the flames are literal and on a building, not an idiom for a man performing brilliantly. “She’s fired up and ready.” does not fit because no energized woman preparing for action appears; firefighters face a literal blaze. “She hasn’t eaten yet.” does not fit because no meal or eating status is visible in the fire response.","explanationJa":"正解は「The house is on fire.」（家が燃えています。）です。家から炎と煙が出ており、消防士が外で消火活動をしています。 「He’s on fire today.」はこの場面とは一致しません。炎は建物で実際に燃えており、男性の絶好調を表す比喩ではありません。 「She’s fired up and ready.」はこの場面とは一致しません。意気込む女性ではなく、消防士が実際の火災に対応しています。 「She hasn’t eaten yet.」はこの場面とは一致しません。消火活動の場面に食事や食べたかどうかの情報はありません。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"The house is on fire.","jp":"家が燃えています。"},{"id":"b","en":"He’s on fire today.","jp":"彼は今日は絶好調です。"},{"id":"c","en":"She’s fired up and ready.","jp":"彼女は気合いが入って準備万端です。"},{"id":"d","en":"She hasn’t eaten yet.","jp":"彼女はまだ食べていません。"}],"correct":"a","image":"/assets/questions/visual/july-18-04-house-on-fire.webp","imageAlt":"Firefighters respond to a house on fire.","visualAssetId":"july-18-04"}'::jsonb, false, 1),
      ('july-18', 'july-18-draft-visual-5', 30, 'See It', 'situation', '{"id":"july-18-draft-visual-5","format":"situation","type":"situation","section":"See It","topic":"idiom","isOriginal":false,"hint":"Read the athlete’s repeated success, dominant performance, and celebration as an idiomatic clue.","hintJa":"選手の連続した成功、圧倒的なプレー、喜ぶ姿を比喩表現の手掛かりにしましょう。","explanation":"“He’s on fire today.” is correct. The athlete performs exceptionally well and celebrates another success in a winning streak. “I have a driver’s license.” does not fit because no license or driving appears; the evidence is athletic performance. “I was supposed to join the class.” does not fit because no missed class or expected attendance is pictured. “I do like this song.” does not fit because no music or emphatic song preference appears; the athlete is celebrating sport.","explanationJa":"正解は「He’s on fire today.」（彼は今日は絶好調です。）です。選手は非常に良いプレーを続け、連勝中の新たな成功を喜んでいます。 「I have a driver’s license.」はこの場面とは一致しません。免許や運転ではなく、競技での活躍が示されています。 「I was supposed to join the class.」はこの場面とは一致しません。参加するはずだった授業や欠席は描かれていません。 「I do like this song.」はこの場面とは一致しません。音楽や曲の好みではなく、選手が競技の成功を喜んでいます。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"He’s on fire today.","jp":"彼は今日は絶好調です。"},{"id":"b","en":"I have a driver’s license.","jp":"運転免許を持っています。"},{"id":"c","en":"I was supposed to join the class.","jp":"そのクラスに参加する予定でした。"},{"id":"d","en":"I do like this song.","jp":"この歌は本当に好きです。"}],"correct":"a","image":"/assets/questions/visual/july-18-05-on-fire-idiom.webp","imageAlt":"An athlete performs brilliantly and celebrates a winning streak.","visualAssetId":"july-18-05"}'::jsonb, false, 1),
      ('july-19', 'july-19-draft-visual-1', 26, 'See It', 'situation', '{"id":"july-19-draft-visual-1","format":"situation","type":"situation","section":"See It","topic":"both","isOriginal":false,"hint":"Notice that neither drink is rejected and each receives the same positive reaction.","hintJa":"どちらの飲み物も断られず、同じように好意的な反応を受けている点を見ましょう。","explanation":"“I like both tea and coffee.” is correct. The person happily accepts and enjoys both the tea and the coffee. “Either day works for me.” does not fit because the two items are drinks, not calendar days or scheduling options. “I’d rather stay home than go out.” does not fit because no home-versus-outing decision appears at the drink table. “I ran into an old friend.” does not fit because no unexpected reunion occurs; one person is comparing beverages.","explanationJa":"正解は「I like both tea and coffee.」（紅茶もコーヒーも両方好きです。）です。人物は紅茶とコーヒーの両方を喜んで受け入れています。 「Either day works for me.」はこの場面とは一致しません。二つは飲み物で、日付や予定候補ではありません。 「I’d rather stay home than go out.」はこの場面とは一致しません。飲み物の場面に、家か外出かの選択はありません。 「I ran into an old friend.」はこの場面とは一致しません。偶然の再会ではなく、一人が飲み物を選んでいます。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"I like both tea and coffee.","jp":"紅茶もコーヒーも両方好きです。"},{"id":"b","en":"Either day works for me.","jp":"どちらの日でも大丈夫です。"},{"id":"c","en":"I’d rather stay home than go out.","jp":"外出するより家にいたいです。"},{"id":"d","en":"I ran into an old friend.","jp":"昔の友人に偶然会いました。"}],"correct":"a","image":"/assets/questions/visual/july-19-01-both-drinks.webp","imageAlt":"A person happily chooses both tea and coffee.","visualAssetId":"july-19-01"}'::jsonb, false, 1),
      ('july-19', 'july-19-draft-visual-2', 27, 'See It', 'situation', '{"id":"july-19-draft-visual-2","format":"situation","type":"situation","section":"See It","topic":"either","isOriginal":false,"hint":"Compare the two calendar dates and the identical approval shown for each.","hintJa":"二つのカレンダーの日付と、それぞれに示された同じ承認を比べましょう。","explanation":"“Either day works for me.” is correct. Two different calendar days receive equal approval, showing no scheduling preference. “I like neither option.” does not fit because both dates receive positive approval, not rejection. “I’d rather not talk about it.” does not fit because the person is openly responding to schedule choices, not avoiding a topic. “I’m on my way to work.” does not fit because no commute or workplace destination appears; the image compares dates.","explanationJa":"正解は「Either day works for me.」（どちらの日でも大丈夫です。）です。異なる二つの日付に同じ承認が示され、どちらの日でも都合がよいことが分かります。 「I like neither option.」はこの場面とは一致しません。両方の日付が肯定されており、どちらも嫌だという反応ではありません。 「I’d rather not talk about it.」はこの場面とは一致しません。話題を避けず、予定候補に明確に答えています。 「I’m on my way to work.」はこの場面とは一致しません。通勤や職場への移動ではなく、日付を比較しています。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"Either day works for me.","jp":"どちらの日でも大丈夫です。"},{"id":"b","en":"I like neither option.","jp":"どちらの選択肢も好きではありません。"},{"id":"c","en":"I’d rather not talk about it.","jp":"できればその話はしたくありません。"},{"id":"d","en":"I’m on my way to work.","jp":"仕事へ向かっている途中です。"}],"correct":"a","image":"/assets/questions/visual/july-19-02-either-day.webp","imageAlt":"A person is equally available on either of two calendar days.","visualAssetId":"july-19-02"}'::jsonb, false, 1),
      ('july-19', 'july-19-draft-visual-3', 28, 'See It', 'situation', '{"id":"july-19-draft-visual-3","format":"situation","type":"situation","section":"See It","topic":"neither","isOriginal":false,"hint":"Read the negative reaction applied equally to the two offered choices.","hintJa":"提示された二つの選択肢の両方に向けられた否定的な反応を見ましょう。","explanation":"“I like neither option.” is correct. The person rejects both displayed options with the same negative response. “I’d rather stay home than go out.” does not fit because the two pictured options are both rejected; they are not home and an outing with one preferred. “That was hilarious.” does not fit because the expression is disapproval, not laughter at something funny. “I won’t have coffee.” does not fit because two options are rejected together; the image does not isolate coffee as the only refusal.","explanationJa":"正解は「I like neither option.」（どちらの選択肢も好きではありません。）です。人物は示された二つの選択肢を、同じ否定的な反応で両方とも断っています。 「I’d rather stay home than go out.」はこの場面とは一致しません。二つとも拒否されており、家と外出の一方を好む選択ではありません。 「That was hilarious.」はこの場面とは一致しません。表情は否定で、面白いことに笑ってはいません。 「I won’t have coffee.」はこの場面とは一致しません。二つを一緒に拒否しており、コーヒーだけを断ってはいません。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"I like neither option.","jp":"どちらの選択肢も好きではありません。"},{"id":"b","en":"I’d rather stay home than go out.","jp":"外出するより家にいたいです。"},{"id":"c","en":"That was hilarious.","jp":"それは爆笑するほど面白かったです。"},{"id":"d","en":"I won’t have coffee.","jp":"コーヒーは飲みません。"}],"correct":"a","image":"/assets/questions/visual/july-19-03-neither-option.webp","imageAlt":"A person rejects both of two options.","visualAssetId":"july-19-03"}'::jsonb, false, 1),
      ('july-19', 'july-19-draft-visual-4', 29, 'See It', 'situation', '{"id":"july-19-draft-visual-4","format":"situation","type":"situation","section":"See It","topic":"would rather","isOriginal":false,"hint":"Compare the person’s relaxed home setup with the declined invitation outside.","hintJa":"家でくつろぐ準備と、外からの誘いを断る様子を比べましょう。","explanation":"“I’d rather stay home than go out.” is correct. The person deliberately chooses the comfortable home activity over going outside. “I’d rather not talk about it.” does not fit because the person declines an outing, not a conversation topic. “I ran into an old friend.” does not fit because no chance meeting or friend reunion occurs; an invitation is being declined. “I like both tea and coffee.” does not fit because the visible contrast is home versus going out, not two beverages.","explanationJa":"正解は「I’d rather stay home than go out.」（外出するより家にいたいです。）です。人物は外出よりも、家でくつろぐ過ごし方を明確に選んでいます。 「I’d rather not talk about it.」はこの場面とは一致しません。話題を避けるのではなく、外出を断っています。 「I ran into an old friend.」はこの場面とは一致しません。偶然の再会ではなく、誘いを断る場面です。 「I like both tea and coffee.」はこの場面とは一致しません。比較は家と外出で、二つの飲み物ではありません。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"I’d rather stay home than go out.","jp":"外出するより家にいたいです。"},{"id":"b","en":"I’d rather not talk about it.","jp":"できればその話はしたくありません。"},{"id":"c","en":"I ran into an old friend.","jp":"昔の友人に偶然会いました。"},{"id":"d","en":"I like both tea and coffee.","jp":"紅茶もコーヒーも両方好きです。"}],"correct":"a","image":"/assets/questions/visual/july-19-04-rather-home.webp","imageAlt":"A person prefers relaxing at home instead of going out.","visualAssetId":"july-19-04"}'::jsonb, false, 1),
      ('july-19', 'july-19-draft-visual-5', 30, 'See It', 'situation', '{"id":"july-19-draft-visual-5","format":"situation","type":"situation","section":"See It","topic":"run into","isOriginal":false,"hint":"Notice the surprise and recognition when the two pedestrians unexpectedly meet.","hintJa":"二人の歩行者が予期せず会った時の驚きと、相手に気づく表情を見ましょう。","explanation":"“I ran into an old friend.” is correct. Two people recognize each other with surprise during an unplanned sidewalk encounter. “I’m on my way to work.” does not fit because the destination is not established; the defining event is the unexpected reunion. “I like both tea and coffee.” does not fit because no drinks or preference comparison appear on the sidewalk. “I’d rather stay home than go out.” does not fit because both people are already outside and meeting; no home preference is shown.","explanationJa":"正解は「I ran into an old friend.」（昔の友人に偶然会いました。）です。二人は歩道で予定外に出会い、驚きながら互いを認識しています。 「I’m on my way to work.」はこの場面とは一致しません。目的地は示されず、重要なのは予期しない再会です。 「I like both tea and coffee.」はこの場面とは一致しません。歩道に飲み物や好みの比較はありません。 「I’d rather stay home than go out.」はこの場面とは一致しません。二人はすでに外で会っており、家にいたいという希望は示されません。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"I ran into an old friend.","jp":"昔の友人に偶然会いました。"},{"id":"b","en":"I’m on my way to work.","jp":"仕事へ向かっている途中です。"},{"id":"c","en":"I like both tea and coffee.","jp":"紅茶もコーヒーも両方好きです。"},{"id":"d","en":"I’d rather stay home than go out.","jp":"外出するより家にいたいです。"}],"correct":"a","image":"/assets/questions/visual/july-19-05-ran-into-friend.webp","imageAlt":"Two old friends unexpectedly meet on a city sidewalk.","visualAssetId":"july-19-05"}'::jsonb, false, 1),
      ('july-22', 'july-22-draft-visual-1', 26, 'See It', 'situation', '{"id":"july-22-draft-visual-1","format":"situation","type":"situation","section":"See It","topic":"availability","isOriginal":false,"hint":"Combine the appointment card, the clock, and the questioning gesture rather than treating them separately.","hintJa":"予定カード、時計、質問する手の動きを別々でなく組み合わせて考えましょう。","explanation":"“Would you be available on August 4th at 10 a.m.?” is correct. The scheduler points to August 4 and 10:00 while asking the other person for availability. “Are you guys ready?” does not fit because one person is being asked about a specific appointment, not a group’s readiness to leave. “Neither is okay.” does not fit because the scene asks about one exact date and time; it does not reject two options. “That’s right. I don’t like it.” does not fit because there is no agreement about disliking an item; the gesture is an open scheduling question.","explanationJa":"正解は「Would you be available on August 4th at 10 a.m.?」（8月4日午前10時はご都合いかがですか？）です。予定を調整する人が8月4日と10時を示し、相手の都合を尋ねています。 「Are you guys ready?」はこの場面とは一致しません。集団の出発準備ではなく、一人に特定日時の都合を尋ねています。 「Neither is okay.」はこの場面とは一致しません。一つの正確な日時を尋ねており、二つの選択肢を拒否してはいません。 「That’s right. I don’t like it.」はこの場面とは一致しません。何かを嫌いだと同意する場面ではなく、予定について質問しています。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"Would you be available on August 4th at 10 a.m.?","jp":"8月4日午前10時はご都合いかがですか？"},{"id":"b","en":"Are you guys ready?","jp":"皆さん、準備はできましたか？"},{"id":"c","en":"Neither is okay.","jp":"どちらも駄目です。"},{"id":"d","en":"That’s right. I don’t like it.","jp":"その通りです。好きではありません。"}],"correct":"a","image":"/assets/questions/visual/july-22-01-availability.webp","imageAlt":"A professional asks whether August 4 at 10 a.m. is available.","visualAssetId":"july-22-01"}'::jsonb, false, 1),
      ('july-22', 'july-22-draft-visual-2', 27, 'See It', 'situation', '{"id":"july-22-draft-visual-2","format":"situation","type":"situation","section":"See It","topic":"you guys","isOriginal":false,"hint":"Look at the whole group’s bags, forward movement, and final readiness check.","hintJa":"グループ全員の荷物、出発する動き、最後の準備確認を見ましょう。","explanation":"“Are you guys ready?” is correct. The group has gathered with their things and one member checks whether everyone can leave. “I like both.” does not fit because no pair of items is being approved; a group is preparing to move. “I prefer cucumber to eggplant.” does not fit because no vegetables or food preference appears among the travelers. “Actually, I do like it.” does not fit because no single object is being emphatically liked; readiness is being checked.","explanationJa":"正解は「Are you guys ready?」（皆さん、準備はできましたか？）です。皆が荷物を持って集まり、一人が全員出発できるか確認しています。 「I like both.」はこの場面とは一致しません。二つの品を好んでいるのではなく、集団が出発準備をしています。 「I prefer cucumber to eggplant.」はこの場面とは一致しません。移動する人々の場面に野菜や食の好みはありません。 「Actually, I do like it.」はこの場面とは一致しません。一つの物を強調して好むのではなく、準備ができたか確認しています。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"Are you guys ready?","jp":"皆さん、準備はできましたか？"},{"id":"b","en":"I like both.","jp":"両方好きです。"},{"id":"c","en":"I prefer cucumber to eggplant.","jp":"ナスよりキュウリの方が好きです。"},{"id":"d","en":"Actually, I do like it.","jp":"実は本当に好きです。"}],"correct":"a","image":"/assets/questions/visual/july-22-02-group-ready.webp","imageAlt":"A group is ready to leave together.","visualAssetId":"july-22-02"}'::jsonb, false, 1),
      ('july-22', 'july-22-draft-visual-3', 28, 'See It', 'situation', '{"id":"july-22-draft-visual-3","format":"situation","type":"situation","section":"See It","topic":"both","isOriginal":false,"hint":"Notice the diner’s equally happy response to each of the two dishes together.","hintJa":"二つの料理それぞれに対する、客の同じように嬉しそうな反応を見ましょう。","explanation":"“I like both.” is correct. The diner enthusiastically approves both dishes rather than choosing only one. “Would you be available on August 4th at 10 a.m.?” does not fit because there is no calendar, clock, or appointment request at the table. “I prefer cucumber to eggplant.” does not fit because the diner gives equal approval, not a preference for one vegetable over another. “Night shifts are still better.” does not fit because no workplace schedule or comparison of shifts appears; the subjects are two dishes.","explanationJa":"正解は「I like both.」（両方好きです。）です。客は一方だけを選ぶのではなく、二つの料理を両方とも気に入っている様子です。 「Would you be available on August 4th at 10 a.m.?」はこの場面とは一致しません。食卓にカレンダー・時計・予定の質問はありません。 「I prefer cucumber to eggplant.」はこの場面とは一致しません。一方の野菜を好むのではなく、両方を同じように喜んでいます。 「Night shifts are still better.」はこの場面とは一致しません。勤務時間の比較ではなく、二つの料理が対象です。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"I like both.","jp":"両方好きです。"},{"id":"b","en":"Would you be available on August 4th at 10 a.m.?","jp":"8月4日午前10時はご都合いかがですか？"},{"id":"c","en":"I prefer cucumber to eggplant.","jp":"ナスよりキュウリの方が好きです。"},{"id":"d","en":"Night shifts are still better.","jp":"それでも夜勤の方がまだいいです。"}],"correct":"a","image":"/assets/questions/visual/july-22-03-like-both.webp","imageAlt":"A diner happily likes both dishes.","visualAssetId":"july-22-03"}'::jsonb, false, 1),
      ('july-22', 'july-22-draft-visual-4', 29, 'See It', 'situation', '{"id":"july-22-draft-visual-4","format":"situation","type":"situation","section":"See It","topic":"neither","isOriginal":false,"hint":"Check the damaged condition of both items and the rejection mark applied to each.","hintJa":"二つの品の壊れた状態と、それぞれに付けられた拒否の印を確認しましょう。","explanation":"“Neither is okay.” is correct. Both offered items are damaged, and each one is clearly rejected as unacceptable. “I prefer cucumber to eggplant.” does not fit because the items are damaged objects, not vegetables being ranked by preference. “That’s right. I don’t like it.” does not fit because the negative judgment applies to two unusable items, not agreement about disliking one thing. “Would you be available on August 4th at 10 a.m.?” does not fit because no date, time, or person’s availability is shown.","explanationJa":"正解は「Neither is okay.」（どちらも駄目です。）です。提示された二つの品はいずれも壊れており、両方とも受け入れられないと示されています。 「I prefer cucumber to eggplant.」はこの場面とは一致しません。壊れた物であり、野菜を好みで比較してはいません。 「That’s right. I don’t like it.」はこの場面とは一致しません。一つを嫌う同意ではなく、使えない二品の両方への否定です。 「Would you be available on August 4th at 10 a.m.?」はこの場面とは一致しません。日付・時刻・人の都合は示されていません。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"Neither is okay.","jp":"どちらも駄目です。"},{"id":"b","en":"I prefer cucumber to eggplant.","jp":"ナスよりキュウリの方が好きです。"},{"id":"c","en":"That’s right. I don’t like it.","jp":"その通りです。好きではありません。"},{"id":"d","en":"Would you be available on August 4th at 10 a.m.?","jp":"8月4日午前10時はご都合いかがですか？"}],"correct":"a","image":"/assets/questions/visual/july-22-04-neither-okay.webp","imageAlt":"Neither of two damaged items is acceptable.","visualAssetId":"july-22-04"}'::jsonb, false, 1),
      ('july-22', 'july-22-draft-visual-5', 30, 'See It', 'situation', '{"id":"july-22-draft-visual-5","format":"situation","type":"situation","section":"See It","topic":"answers","isOriginal":false,"hint":"Identify the food being eaten and the diner’s unmistakably positive reaction.","hintJa":"食べている料理と、客の明らかに好意的な反応を確認しましょう。","explanation":"“Yes, I do. I like yakiniku.” is correct. The diner eats yakiniku enthusiastically and responds positively to the food. “Would you be available on August 4th at 10 a.m.?” does not fit because there is no scheduling card or time request; the scene is about enjoying food. “Neither is okay.” does not fit because the diner positively accepts the visible food rather than rejecting two items. “Night shifts are still better.” does not fit because no work shift or schedule comparison appears at the yakiniku table.","explanationJa":"正解は「Yes, I do. I like yakiniku.」（はい、焼肉が好きです。）です。客は焼肉をおいしそうに食べ、その料理を気に入っていることが分かります。 「Would you be available on August 4th at 10 a.m.?」はこの場面とは一致しません。予定カードや時刻の質問はなく、料理を楽しむ場面です。 「Neither is okay.」はこの場面とは一致しません。二つを拒否するのではなく、目の前の料理を肯定的に受け入れています。 「Night shifts are still better.」はこの場面とは一致しません。焼肉の食卓に勤務時間や予定の比較はありません。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"Yes, I do. I like yakiniku.","jp":"はい、焼肉が好きです。"},{"id":"b","en":"Would you be available on August 4th at 10 a.m.?","jp":"8月4日午前10時はご都合いかがですか？"},{"id":"c","en":"Neither is okay.","jp":"どちらも駄目です。"},{"id":"d","en":"Night shifts are still better.","jp":"それでも夜勤の方がまだいいです。"}],"correct":"a","image":"/assets/questions/visual/july-22-05-likes-yakiniku.webp","imageAlt":"A diner enthusiastically enjoys yakiniku.","visualAssetId":"july-22-05"}'::jsonb, false, 1),
      ('july-23', 'july-23-draft-visual-1', 26, 'See It', 'situation', '{"id":"july-23-draft-visual-1","format":"situation","type":"situation","section":"See It","topic":"health","isOriginal":false,"hint":"Use the person’s low energy, thermometer, and resting-at-home behavior.","hintJa":"人物の元気のなさ、体温計、家で休む様子を手掛かりにしましょう。","explanation":"“I’m feeling under the weather.” is correct. The person rests at home with mild symptoms and looks slightly unwell rather than seriously ill. “It’s too hot to go outside.” does not fit because no extreme heat, sun, or blocked outing appears; the person has mild illness symptoms. “It fell on the floor.” does not fit because no object has fallen; the focal evidence is the person’s physical condition. “I ordered a chicken-and-egg rice bowl.” does not fit because no restaurant order or rice bowl appears in the home recovery scene.","explanationJa":"正解は「I’m feeling under the weather.」（少し体調がよくありません。）です。人物は軽い体調不良の様子で、自宅で静かに休んでいます。 「It’s too hot to go outside.」はこの場面とは一致しません。猛暑や日差し、外出断念ではなく、軽い病気の症状があります。 「It fell on the floor.」はこの場面とは一致しません。床に落ちた物はなく、人物の体調が中心です。 「I ordered a chicken-and-egg rice bowl.」はこの場面とは一致しません。自宅で休む場面に注文や親子丼はありません。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"I’m feeling under the weather.","jp":"少し体調がよくありません。"},{"id":"b","en":"It’s too hot to go outside.","jp":"暑すぎて外に出られません。"},{"id":"c","en":"It fell on the floor.","jp":"それは床に落ちました。"},{"id":"d","en":"I ordered a chicken-and-egg rice bowl.","jp":"親子丼を注文しました。"}],"correct":"a","image":"/assets/questions/visual/july-23-01-under-weather.webp","imageAlt":"A person feels mildly ill at home.","visualAssetId":"july-23-01"}'::jsonb, false, 1),
      ('july-23', 'july-23-draft-visual-2', 27, 'See It', 'situation', '{"id":"july-23-draft-visual-2","format":"situation","type":"situation","section":"See It","topic":"too...to","isOriginal":false,"hint":"Compare the intense outdoor heat with the person stopping at the doorway.","hintJa":"外の激しい暑さと、玄関で出るのをやめる人物を比べましょう。","explanation":"“It’s too hot to go outside.” is correct. Severe heat outside makes the person turn back instead of leaving the cool interior. “I’ve just ordered lunch.” does not fit because no food order or restaurant interaction is visible; weather prevents an outing. “It’s lying on the floor.” does not fit because no object on the floor is central; the doorway and outdoor heat are the evidence. “Doraemon is a cat-shaped robot.” does not fit because no character or robot appears; the scene concerns dangerous heat.","explanationJa":"正解は「It’s too hot to go outside.」（暑すぎて外に出られません。）です。外の厳しい暑さのため、人物は涼しい室内から出るのをやめています。 「I’ve just ordered lunch.」はこの場面とは一致しません。食事注文やレストランのやり取りはなく、暑さが外出を妨げています。 「It’s lying on the floor.」はこの場面とは一致しません。床の物ではなく、玄関と外の暑さが手掛かりです。 「Doraemon is a cat-shaped robot.」はこの場面とは一致しません。キャラクターやロボットはなく、危険な暑さの場面です。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"It’s too hot to go outside.","jp":"暑すぎて外に出られません。"},{"id":"b","en":"I’ve just ordered lunch.","jp":"たった今昼食を注文しました。"},{"id":"c","en":"It’s lying on the floor.","jp":"それは床に落ちています。"},{"id":"d","en":"Doraemon is a cat-shaped robot.","jp":"ドラえもんは猫型ロボットです。"}],"correct":"a","image":"/assets/questions/visual/july-23-02-too-hot-outside.webp","imageAlt":"It is too hot for a person to go outside.","visualAssetId":"july-23-02"}'::jsonb, false, 1),
      ('july-23', 'july-23-draft-visual-3', 28, 'See It', 'situation', '{"id":"july-23-draft-visual-3","format":"situation","type":"situation","section":"See It","topic":"movement","isOriginal":false,"hint":"Notice the car emerging without warning and the pedestrian’s immediate surprise.","hintJa":"車が前触れなく出てくる動きと、歩行者の即座の驚きを見ましょう。","explanation":"“A car suddenly appeared.” is correct. A car abruptly emerges from a side street, surprising the nearby pedestrian. “It fell on the floor.” does not fit because the moving object is a car entering the street, not an item dropping downward. “I just got home.” does not fit because no arrival at a residence is shown; the event occurs on a street. “I haven’t thought of one yet.” does not fit because no idea-generation conversation occurs; the person reacts to immediate traffic.","explanationJa":"正解は「A car suddenly appeared.」（車が突然現れました。）です。脇道から車が突然現れ、近くの歩行者を驚かせています。 「It fell on the floor.」はこの場面とは一致しません。動いているのは道路へ出る車で、物が床へ落ちたのではありません。 「I just got home.」はこの場面とは一致しません。自宅への到着ではなく、道路上の出来事です。 「I haven’t thought of one yet.」はこの場面とは一致しません。案を考える会話ではなく、目の前の交通に反応しています。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"A car suddenly appeared.","jp":"車が突然現れました。"},{"id":"b","en":"It fell on the floor.","jp":"それは床に落ちました。"},{"id":"c","en":"I just got home.","jp":"たった今家に着きました。"},{"id":"d","en":"I haven’t thought of one yet.","jp":"まだ一つも思いついていません。"}],"correct":"a","image":"/assets/questions/visual/july-23-03-car-appeared.webp","imageAlt":"A car suddenly appears from a side street.","visualAssetId":"july-23-03"}'::jsonb, false, 1),
      ('july-23', 'july-23-draft-visual-4', 29, 'See It', 'situation', '{"id":"july-23-draft-visual-4","format":"situation","type":"situation","section":"See It","topic":"food","isOriginal":false,"hint":"Identify the finished dish being handed to the waiting customer.","hintJa":"待っている客に渡される完成した料理が何か確認しましょう。","explanation":"“I ordered a chicken-and-egg rice bowl.” is correct. The server delivers a chicken-and-egg rice bowl that the customer selected. “Doraemon is a cat-shaped robot.” does not fit because no animated character or robot appears in the restaurant. “I’m feeling under the weather.” does not fit because the customer is awaiting food, with no symptom or illness cue. “It fell on the floor.” does not fit because the bowl is carried safely to the table and has not fallen.","explanationJa":"正解は「I ordered a chicken-and-egg rice bowl.」（親子丼を注文しました。）です。店員が、客の選んだ鶏肉と卵の丼料理を届けています。 「Doraemon is a cat-shaped robot.」はこの場面とは一致しません。レストランにアニメのキャラクターやロボットはありません。 「I’m feeling under the weather.」はこの場面とは一致しません。客は料理を待っており、病気の症状は示されません。 「It fell on the floor.」はこの場面とは一致しません。丼は安全にテーブルへ運ばれ、床に落ちていません。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"I ordered a chicken-and-egg rice bowl.","jp":"親子丼を注文しました。"},{"id":"b","en":"Doraemon is a cat-shaped robot.","jp":"ドラえもんは猫型ロボットです。"},{"id":"c","en":"I’m feeling under the weather.","jp":"少し体調がよくありません。"},{"id":"d","en":"It fell on the floor.","jp":"それは床に落ちました。"}],"correct":"a","image":"/assets/questions/visual/july-23-04-oyakodon-order.webp","imageAlt":"A customer receives a chicken-and-egg rice bowl.","visualAssetId":"july-23-04"}'::jsonb, false, 1),
      ('july-23', 'july-23-draft-visual-5', 30, 'See It', 'situation', '{"id":"july-23-draft-visual-5","format":"situation","type":"situation","section":"See It","topic":"Doraemon","isOriginal":false,"hint":"Compare the ordinary doorway with the distant tropical place visible immediately through it.","hintJa":"普通の場所に立つドアと、開いた先にすぐ見える遠い南国を比べましょう。","explanation":"“The Anywhere Door can take you anywhere.” is correct. The freestanding magical door opens directly onto a faraway tropical destination. “I haven’t thought of one yet.” does not fit because no person struggles to produce an idea; the door visibly provides transportation. “I’ve just ordered lunch.” does not fit because no meal, menu, or order appears around the magical doorway. “I put it on the floor.” does not fit because the doorway stands upright and connects places; no object is being placed on the floor.","explanationJa":"正解は「The Anywhere Door can take you anywhere.」（どこでもドアならどこへでも行けます。）です。独立して立つ不思議なドアが、遠くの南国へ直接つながっています。 「I haven’t thought of one yet.」はこの場面とは一致しません。案を思いつけない人物ではなく、ドアが移動手段として描かれています。 「I’ve just ordered lunch.」はこの場面とは一致しません。不思議なドアの周囲に食事・メニュー・注文はありません。 「I put it on the floor.」はこの場面とは一致しません。ドアは立って場所をつないでおり、物を床に置いてはいません。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"The Anywhere Door can take you anywhere.","jp":"どこでもドアならどこへでも行けます。"},{"id":"b","en":"I haven’t thought of one yet.","jp":"まだ一つも思いついていません。"},{"id":"c","en":"I’ve just ordered lunch.","jp":"たった今昼食を注文しました。"},{"id":"d","en":"I put it on the floor.","jp":"それを床に置きました。"}],"correct":"a","image":"/assets/questions/visual/july-23-05-anywhere-door.webp","imageAlt":"A magical freestanding door opens onto a distant tropical place.","visualAssetId":"july-23-05"}'::jsonb, false, 1),
      ('july-25', 'july-25-draft-visual-1', 26, 'See It', 'situation', '{"id":"july-25-draft-visual-1","format":"situation","type":"situation","section":"See It","topic":"getting","isOriginal":false,"hint":"Notice the gradual change in appetite as lunchtime approaches.","hintJa":"昼食時刻が近づくにつれて、食欲が徐々に変化する様子を見ましょう。","explanation":"“I’m getting hungry.” is correct. Before lunch, the person begins to notice a growing desire for food. “I’m frustrated because nothing is working.” does not fit because no broken device or failed attempt appears; the change is physical appetite. “It’s getting cold.” does not fit because no temperature drop or winter cue appears; the person is thinking about food. “No one knows the answer.” does not fit because no question or group lacking knowledge is shown.","explanationJa":"正解は「I’m getting hungry.」（お腹が空いてきました。）です。昼食前、人物は食べたい気持ちが徐々に強くなるのを感じています。 「I’m frustrated because nothing is working.」はこの場面とは一致しません。壊れた機器や失敗ではなく、身体的な食欲の変化です。 「It’s getting cold.」はこの場面とは一致しません。気温低下や冬の手掛かりはなく、食べ物を考えています。 「No one knows the answer.」はこの場面とは一致しません。問題や答えを知らない集団は描かれていません。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"I’m getting hungry.","jp":"お腹が空いてきました。"},{"id":"b","en":"I’m frustrated because nothing is working.","jp":"何もうまくいかず、もどかしいです。"},{"id":"c","en":"It’s getting cold.","jp":"寒くなってきました。"},{"id":"d","en":"No one knows the answer.","jp":"誰も答えを知りません。"}],"correct":"a","image":"/assets/questions/visual/july-25-01-getting-hungry.webp","imageAlt":"A person gradually starts to feel hungry before lunch.","visualAssetId":"july-25-01"}'::jsonb, false, 1),
      ('july-25', 'july-25-draft-visual-2', 27, 'See It', 'situation', '{"id":"july-25-draft-visual-2","format":"situation","type":"situation","section":"See It","topic":"hunger","isOriginal":false,"hint":"Use the completely empty table and the person’s extreme physical reaction to hunger.","hintJa":"何もないテーブルと、空腹に対する人物の強い身体反応を見ましょう。","explanation":"“I’m starving.” is correct. The person waits at an empty table with an intense, urgent need for food. “I’m annoyed by the noise.” does not fit because no sound source or ear-covering reaction appears; the distress comes from hunger. “He’s making me nervous.” does not fit because no other man is causing anxiety; the person reacts to an empty stomach. “Is anyone there?” does not fit because the person is not calling into an empty place; attention is fixed on the lack of food.","explanationJa":"正解は「I’m starving.」（もう腹ペコです。）です。人物は何もない食卓で、今すぐ食べ物が必要なほど強い空腹を感じています。 「I’m annoyed by the noise.」はこの場面とは一致しません。音源や耳をふさぐ反応はなく、苦しさの原因は空腹です。 「He’s making me nervous.」はこの場面とは一致しません。不安にさせる男性はおらず、空腹に反応しています。 「Is anyone there?」はこの場面とは一致しません。誰かを呼んでいるのではなく、食べ物がないことに注意が向いています。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"I’m starving.","jp":"もう腹ペコです。"},{"id":"b","en":"I’m annoyed by the noise.","jp":"その音にイライラしています。"},{"id":"c","en":"He’s making me nervous.","jp":"彼のせいで不安になっています。"},{"id":"d","en":"Is anyone there?","jp":"誰かいますか？"}],"correct":"a","image":"/assets/questions/visual/july-25-02-starving.webp","imageAlt":"An extremely hungry person waits at an empty table.","visualAssetId":"july-25-02"}'::jsonb, false, 1),
      ('july-25', 'july-25-draft-visual-3', 28, 'See It', 'situation', '{"id":"july-25-draft-visual-3","format":"situation","type":"situation","section":"See It","topic":"feelings","isOriginal":false,"hint":"Trace the construction sound toward the person covering an ear and frowning.","hintJa":"工事音が、耳をふさいで顔をしかめる人物へ届く様子を追いましょう。","explanation":"“I’m annoyed by the noise.” is correct. Loud construction reaches the person, whose frown and covered ear show irritation. “I’m frustrated because nothing is working.” does not fit because no equipment is failing; one clearly visible noise source causes the reaction. “It’s getting cold.” does not fit because the person reacts to sound, not falling temperature. “No one knows the answer.” does not fit because no question or uncertain group appears in the construction scene.","explanationJa":"正解は「I’m annoyed by the noise.」（その音にイライラしています。）です。大きな工事音が人物に届き、しかめた顔と耳をふさぐ動作が苛立ちを示しています。 「I’m frustrated because nothing is working.」はこの場面とは一致しません。機器の故障ではなく、一つの明確な騒音源が反応を引き起こしています。 「It’s getting cold.」はこの場面とは一致しません。気温の低下ではなく、音に反応しています。 「No one knows the answer.」はこの場面とは一致しません。工事の場面に問題や答えを知らない集団はありません。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"I’m annoyed by the noise.","jp":"その音にイライラしています。"},{"id":"b","en":"I’m frustrated because nothing is working.","jp":"何もうまくいかず、もどかしいです。"},{"id":"c","en":"It’s getting cold.","jp":"寒くなってきました。"},{"id":"d","en":"No one knows the answer.","jp":"誰も答えを知りません。"}],"correct":"a","image":"/assets/questions/visual/july-25-03-annoyed-noise.webp","imageAlt":"A person is annoyed by loud construction noise.","visualAssetId":"july-25-03"}'::jsonb, false, 1),
      ('july-25', 'july-25-draft-visual-4', 29, 'See It', 'situation', '{"id":"july-25-draft-visual-4","format":"situation","type":"situation","section":"See It","topic":"nerves","isOriginal":false,"hint":"Identify who keeps calling and how the repeated notifications change the recipient’s mood.","hintJa":"誰が繰り返し電話し、その通知で受け手の気分がどう変わるか見ましょう。","explanation":"“He’s getting on my nerves.” is correct. Repeated calls from the same identifiable man progressively irritate the phone’s owner. “I’m starving.” does not fit because the distress is triggered by repeated calls, not an empty table or need for food. “Have you ever been hypnotized?” does not fit because no hypnosis or past-experience question appears; the phone identifies the irritating caller. “No one knows the answer.” does not fit because no unanswered question or group appears; one caller is the clear source of annoyance.","explanationJa":"正解は「He’s getting on my nerves.」（彼にはだんだんイライラしてきました。）です。同じ男性から繰り返しかかってくる電話が、持ち主を次第に苛立たせています。 「I’m starving.」はこの場面とは一致しません。苦しさの原因は繰り返しかかってくる電話で、食べ物がないことではありません。 「Have you ever been hypnotized?」はこの場面とは一致しません。催眠や経験を尋ねる会話ではなく、電話が苛立たせる相手を示しています。 「No one knows the answer.」はこの場面とは一致しません。未解決の問題や集団ではなく、一人の発信者が苛立ちの原因です。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"He’s getting on my nerves.","jp":"彼にはだんだんイライラしてきました。"},{"id":"b","en":"I’m starving.","jp":"もう腹ペコです。"},{"id":"c","en":"Have you ever been hypnotized?","jp":"催眠をかけられたことがありますか？"},{"id":"d","en":"No one knows the answer.","jp":"誰も答えを知りません。"}],"correct":"a","image":"/assets/questions/visual/july-25-04-on-my-nerves.webp","imageAlt":"Repeated phone notifications are getting on a person''s nerves.","visualAssetId":"july-25-04"}'::jsonb, false, 1),
      ('july-25', 'july-25-draft-visual-5', 30, 'See It', 'situation', '{"id":"july-25-draft-visual-5","format":"situation","type":"situation","section":"See It","topic":"intuition","isOriginal":false,"hint":"Read the person’s hesitation and bodily warning before entering the dark alley.","hintJa":"暗い路地へ入る前のためらいと、身体が警告するような反応を読み取りましょう。","explanation":"“I have a gut feeling that something is wrong.” is correct. Before entering the dark alley, the person stops because an instinctive warning suggests danger. “Is anyone there?” does not fit because the person does not call out for someone; the response is an internal warning. “I’m getting hungry.” does not fit because no food or appetite cue appears; the physical feeling concerns danger. “He’s getting on my nerves.” does not fit because no irritating man or repeated action appears; the alley itself triggers unease.","explanationJa":"正解は「I have a gut feeling that something is wrong.」（何かがおかしい気がします。）です。暗い路地へ入る前、直感的な警告で危険を感じて立ち止まっています。 「Is anyone there?」はこの場面とは一致しません。誰かを呼んでいるのではなく、自分の内側の警告に反応しています。 「I’m getting hungry.」はこの場面とは一致しません。食べ物や食欲の手掛かりはなく、身体感覚は危険に関するものです。 「He’s getting on my nerves.」はこの場面とは一致しません。苛立たせる男性や反復行動はなく、路地が不安を引き起こしています。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"I have a gut feeling that something is wrong.","jp":"何かがおかしい気がします。"},{"id":"b","en":"Is anyone there?","jp":"誰かいますか？"},{"id":"c","en":"I’m getting hungry.","jp":"お腹が空いてきました。"},{"id":"d","en":"He’s getting on my nerves.","jp":"彼にはだんだんイライラしてきました。"}],"correct":"a","image":"/assets/questions/visual/july-25-05-gut-feeling.webp","imageAlt":"A person trusts a bad gut feeling before entering a dark alley.","visualAssetId":"july-25-05"}'::jsonb, false, 1),
      ('july-26', 'july-26-draft-visual-1', 26, 'See It', 'situation', '{"id":"july-26-draft-visual-1","format":"situation","type":"situation","section":"See It","topic":"hope","isOriginal":false,"hint":"Use the future calendar, Malaysia travel image, and hopeful planning posture.","hintJa":"来年のカレンダー、マレーシア旅行のイメージ、希望を持つ姿勢を手掛かりにしましょう。","explanation":"“I hope I can visit Malaysia next year.” is correct. The traveler looks ahead to next year and hopes for a future visit to Malaysia. “I have already eaten breakfast.” does not fit because no breakfast or completed meal appears; the focus is a future travel hope. “I have lived here since 2016.” does not fit because no residence timeline beginning in 2016 is shown. “I haven’t taken a bath yet.” does not fit because no bathroom or unfinished bathing routine appears in the travel plan.","explanationJa":"正解は「I hope I can visit Malaysia next year.」（来年マレーシアへ行けるといいな。）です。旅行者は来年を見据え、将来マレーシアを訪れたいと願っています。 「I have already eaten breakfast.」はこの場面とは一致しません。朝食や食事完了ではなく、将来の旅行への希望です。 「I have lived here since 2016.」はこの場面とは一致しません。2016年から続く居住期間は示されていません。 「I haven’t taken a bath yet.」はこの場面とは一致しません。旅行計画の場面に浴室や未完了の入浴はありません。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"I hope I can visit Malaysia next year.","jp":"来年マレーシアへ行けるといいな。"},{"id":"b","en":"I have already eaten breakfast.","jp":"もう朝食を食べました。"},{"id":"c","en":"I have lived here since 2016.","jp":"2016年からここに住んでいます。"},{"id":"d","en":"I haven’t taken a bath yet.","jp":"まだお風呂に入っていません。"}],"correct":"a","image":"/assets/questions/visual/july-26-01-hope-malaysia.webp","imageAlt":"A hopeful traveler plans to visit Malaysia next year.","visualAssetId":"july-26-01"}'::jsonb, false, 1),
      ('july-26', 'july-26-draft-visual-2', 27, 'See It', 'situation', '{"id":"july-26-draft-visual-2","format":"situation","type":"situation","section":"See It","topic":"wish","isOriginal":false,"hint":"Compare the rainy present location with the sunny Malaysian scene the person imagines.","hintJa":"雨の現在地と、人物が思い描く晴れたマレーシアを比べましょう。","explanation":"“I wish I were in Malaysia now.” is correct. Stuck in a rainy room, the person imagines being in sunny Malaysia at this moment. “I wish I had studied harder.” does not fit because there is no test, book, or regret about past study; the desired alternative is a present location. “I haven’t eaten dinner yet.” does not fit because no meal or unfinished dinner appears; the contrast is between two places. “I had already eaten when you arrived.” does not fit because no arrival or earlier completed meal is shown in the imagined travel scene.","explanationJa":"正解は「I wish I were in Malaysia now.」（今マレーシアにいたらいいのに。）です。雨の部屋にいる人物が、今この瞬間に晴れたマレーシアにいたらいいのにと想像しています。 「I wish I had studied harder.」はこの場面とは一致しません。試験・本・過去の勉強への後悔はなく、今いる場所を変えたい願いです。 「I haven’t eaten dinner yet.」はこの場面とは一致しません。食事や未完了の夕食ではなく、二つの場所の対比です。 「I had already eaten when you arrived.」はこの場面とは一致しません。誰かの到着や、それ以前に済ませた食事は描かれていません。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"I wish I were in Malaysia now.","jp":"今マレーシアにいたらいいのに。"},{"id":"b","en":"I wish I had studied harder.","jp":"もっと勉強しておけばよかった。"},{"id":"c","en":"I haven’t eaten dinner yet.","jp":"まだ夕食を食べていません。"},{"id":"d","en":"I had already eaten when you arrived.","jp":"あなたが到着した時にはもう食べていました。"}],"correct":"a","image":"/assets/questions/visual/july-26-02-wish-in-malaysia.webp","imageAlt":"A person in a rainy room wishes they were in sunny Malaysia.","visualAssetId":"july-26-02"}'::jsonb, false, 1),
      ('july-26', 'july-26-draft-visual-3', 28, 'See It', 'situation', '{"id":"july-26-draft-visual-3","format":"situation","type":"situation","section":"See It","topic":"regret","isOriginal":false,"hint":"Look at the disappointing test result and the unused study materials from before the test.","hintJa":"残念な試験結果と、試験前に十分使われなかった教材を見ましょう。","explanation":"“I wish I had studied harder.” is correct. After receiving a poor result, the learner regrets the lack of sufficient study beforehand. “I wish I had been born there.” does not fit because no birthplace or country of birth appears; the regret concerns preparation for a test. “I’ve just arrived home.” does not fit because no doorway, luggage, or recent home arrival is shown. “I haven’t taken a bath yet.” does not fit because no bathing routine is relevant to the test paper and study books.","explanationJa":"正解は「I wish I had studied harder.」（もっと勉強しておけばよかった。）です。悪い結果を受け取り、学習者は事前に十分勉強しなかったことを後悔しています。 「I wish I had been born there.」はこの場面とは一致しません。出生地ではなく、試験への準備不足を後悔しています。 「I’ve just arrived home.」はこの場面とは一致しません。玄関・荷物・帰宅したばかりの様子はありません。 「I haven’t taken a bath yet.」はこの場面とは一致しません。試験用紙や教材に、入浴の状況は関係ありません。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"I wish I had studied harder.","jp":"もっと勉強しておけばよかった。"},{"id":"b","en":"I wish I had been born there.","jp":"そこで生まれていたらよかった。"},{"id":"c","en":"I’ve just arrived home.","jp":"たった今家に着きました。"},{"id":"d","en":"I haven’t taken a bath yet.","jp":"まだお風呂に入っていません。"}],"correct":"a","image":"/assets/questions/visual/july-26-03-studied-harder.webp","imageAlt":"A learner regrets not studying harder before a test.","visualAssetId":"july-26-03"}'::jsonb, false, 1),
      ('july-26', 'july-26-draft-visual-4', 29, 'See It', 'situation', '{"id":"july-26-draft-visual-4","format":"situation","type":"situation","section":"See It","topic":"present perfect","isOriginal":false,"hint":"Notice the empty breakfast plate and the evidence that the morning meal is complete now.","hintJa":"空になった朝食の皿と、朝の食事が今すでに終わっている証拠を見ましょう。","explanation":"“I have already eaten breakfast.” is correct. The breakfast dishes are empty, showing the person has completed the meal already. “I haven’t eaten dinner yet.” does not fit because the pictured meal is a completed breakfast, not an unfinished dinner. “I had finished dinner before he called.” does not fit because there is no dinner or phone-call sequence; only the present result of breakfast is shown. “I hope I can visit Malaysia next year.” does not fit because no map, calendar, or travel hope appears at the breakfast table.","explanationJa":"正解は「I have already eaten breakfast.」（もう朝食を食べました。）です。朝食の食器が空で、人物がすでに食事を終えたことを示しています。 「I haven’t eaten dinner yet.」はこの場面とは一致しません。描かれているのは完了した朝食で、まだ食べていない夕食ではありません。 「I had finished dinner before he called.」はこの場面とは一致しません。夕食や電話の前後関係はなく、朝食を終えた現在の結果だけが示されています。 「I hope I can visit Malaysia next year.」はこの場面とは一致しません。朝食の食卓に地図・カレンダー・旅行の希望はありません。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"I have already eaten breakfast.","jp":"もう朝食を食べました。"},{"id":"b","en":"I haven’t eaten dinner yet.","jp":"まだ夕食を食べていません。"},{"id":"c","en":"I had finished dinner before he called.","jp":"彼が電話する前に夕食を終えていました。"},{"id":"d","en":"I hope I can visit Malaysia next year.","jp":"来年マレーシアへ行けるといいな。"}],"correct":"a","image":"/assets/questions/visual/july-26-04-already-breakfast.webp","imageAlt":"A person has already finished breakfast.","visualAssetId":"july-26-04"}'::jsonb, false, 1),
      ('july-26', 'july-26-draft-visual-5', 30, 'See It', 'situation', '{"id":"july-26-draft-visual-5","format":"situation","type":"situation","section":"See It","topic":"past perfect","isOriginal":false,"hint":"Establish the order: the empty dinner setting comes before the incoming call.","hintJa":"順序を確認しましょう。空になった夕食の食卓が先で、電話の着信が後です。","explanation":"“I had finished dinner before he called.” is correct. Dinner is already finished when the later phone call arrives. “I hope I can visit Malaysia next year.” does not fit because no future trip or Malaysia image appears; the visual establishes two past events. “I haven’t eaten dinner yet.” does not fit because the empty dishes show dinner is complete, directly contradicting an uneaten meal. “I haven’t taken a bath yet.” does not fit because no bathroom or bathing status appears; the later event is a phone call.","explanationJa":"正解は「I had finished dinner before he called.」（彼が電話する前に夕食を終えていました。）です。後から電話がかかってきた時には、夕食はすでに終わっています。 「I hope I can visit Malaysia next year.」はこの場面とは一致しません。将来の旅行やマレーシアではなく、過去の二つの出来事の順序です。 「I haven’t eaten dinner yet.」はこの場面とは一致しません。空の食器は夕食完了を示し、まだ食べていない状態と矛盾します。 「I haven’t taken a bath yet.」はこの場面とは一致しません。浴室や入浴状況はなく、後の出来事は電話です。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"I had finished dinner before he called.","jp":"彼が電話する前に夕食を終えていました。"},{"id":"b","en":"I hope I can visit Malaysia next year.","jp":"来年マレーシアへ行けるといいな。"},{"id":"c","en":"I haven’t eaten dinner yet.","jp":"まだ夕食を食べていません。"},{"id":"d","en":"I haven’t taken a bath yet.","jp":"まだお風呂に入っていません。"}],"correct":"a","image":"/assets/questions/visual/july-26-05-dinner-before-call.webp","imageAlt":"Dinner was finished before a phone call arrived.","visualAssetId":"july-26-05"}'::jsonb, false, 1),
      ('july-27', 'july-27-draft-visual-1', 26, 'See It', 'situation', '{"id":"july-27-draft-visual-1","format":"situation","type":"situation","section":"See It","topic":"spill","isOriginal":false,"hint":"Identify the liquid, where it lands, and the person’s accidental reaction.","hintJa":"液体の種類、落ちた場所、人物の思いがけない反応を確認しましょう。","explanation":"“I spilled coffee on my shirt.” is correct. Coffee spills accidentally from the cup and leaves a visible stain on the person’s white shirt. “She poured sauce over the pasta.” does not fit because the liquid is coffee landing accidentally on clothing, not sauce deliberately added to pasta. “This dessert has a sophisticated flavor.” does not fit because no dessert tasting or refined flavor reaction appears; the person reacts to a stain. “I had eaten before he arrived.” does not fit because no man’s arrival or sequence of completed eating appears.","explanationJa":"正解は「I spilled coffee on my shirt.」（シャツにコーヒーをこぼしました。）です。カップからコーヒーが偶然こぼれ、人物の白いシャツに明確なしみができています。 「She poured sauce over the pasta.」はこの場面とは一致しません。液体は服に偶然かかったコーヒーで、パスタへ意図的にかけるソースではありません。 「This dessert has a sophisticated flavor.」はこの場面とは一致しません。デザートの試食や洗練された味への反応ではなく、しみに驚いています。 「I had eaten before he arrived.」はこの場面とは一致しません。男性の到着や、それ以前に食べ終えた時間関係はありません。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"I spilled coffee on my shirt.","jp":"シャツにコーヒーをこぼしました。"},{"id":"b","en":"She poured sauce over the pasta.","jp":"彼女はパスタにソースをかけました。"},{"id":"c","en":"This dessert has a sophisticated flavor.","jp":"このデザートは洗練された味です。"},{"id":"d","en":"I had eaten before he arrived.","jp":"彼が着く前に食べていました。"}],"correct":"a","image":"/assets/questions/visual/july-27-01-spilled-coffee.webp","imageAlt":"A person accidentally spills coffee on a white shirt.","visualAssetId":"july-27-01"}'::jsonb, false, 1),
      ('july-27', 'july-27-draft-visual-2', 27, 'See It', 'situation', '{"id":"july-27-draft-visual-2","format":"situation","type":"situation","section":"See It","topic":"pour","isOriginal":false,"hint":"Observe who controls the container, what flows out, and the food receiving it.","hintJa":"容器を持つ人物、流れ出る物、それを受ける料理を見ましょう。","explanation":"“She poured sauce over the pasta.” is correct. An adult woman intentionally tips the container so sauce flows directly over the pasta. “He splashed water on me.” does not fit because the actor is a woman pouring sauce carefully onto food, not a man splashing water at a person. “He plays tennis every week.” does not fit because no man, racket, court, or repeated sports routine appears in the kitchen. “I used to live here.” does not fit because no former home or past residence is indicated; the action is food preparation.","explanationJa":"正解は「She poured sauce over the pasta.」（彼女はパスタにソースをかけました。）です。成人女性が容器を意図的に傾け、ソースをパスタへ直接流しかけています。 「He splashed water on me.」はこの場面とは一致しません。女性が料理へ丁寧にソースを注いでおり、男性が人へ水をはねかけてはいません。 「He plays tennis every week.」はこの場面とは一致しません。台所に男性・ラケット・コート・毎週の競技習慣はありません。 「I used to live here.」はこの場面とは一致しません。以前の住居や過去の居住は示されず、料理を仕上げています。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"She poured sauce over the pasta.","jp":"彼女はパスタにソースをかけました。"},{"id":"b","en":"He splashed water on me.","jp":"彼は私に水をバシャッとかけました。"},{"id":"c","en":"He plays tennis every week.","jp":"彼は毎週テニスをします。"},{"id":"d","en":"I used to live here.","jp":"昔はここに住んでいました。"}],"correct":"a","image":"/assets/questions/visual/july-27-02-poured-sauce.webp","imageAlt":"A woman deliberately pours sauce over pasta.","visualAssetId":"july-27-02"}'::jsonb, false, 1),
      ('july-27', 'july-27-draft-visual-3', 28, 'See It', 'situation', '{"id":"july-27-draft-visual-3","format":"situation","type":"situation","section":"See It","topic":"splash","isOriginal":false,"hint":"Track the water from the man’s motion to the woman who receives the splash.","hintJa":"男性の動きから、女性にかかる水までを追いましょう。","explanation":"“He splashed water on me.” is correct. A man sends a visible splash of water onto a woman, who reacts to being hit by it. “Coffee can be an acquired taste.” does not fit because no coffee or gradual change in taste appears; the visible action is water splashing. “I went to Malaysia last year.” does not fit because no travel, map, or past-year cue appears in the playful water scene. “I wish I had been invited.” does not fit because no invitation or exclusion is shown; two people interact directly.","explanationJa":"正解は「He splashed water on me.」（彼は私に水をバシャッとかけました。）です。男性が女性へ目に見える水しぶきを飛ばし、女性は水がかかって驚いています。 「Coffee can be an acquired taste.」はこの場面とは一致しません。コーヒーや味への慣れではなく、水をかける動作です。 「I went to Malaysia last year.」はこの場面とは一致しません。水遊びの場面に旅行・地図・昨年の手掛かりはありません。 「I wish I had been invited.」はこの場面とは一致しません。招待や仲間外れではなく、二人が直接やり取りしています。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"He splashed water on me.","jp":"彼は私に水をバシャッとかけました。"},{"id":"b","en":"Coffee can be an acquired taste.","jp":"コーヒーは慣れると好きになる味です。"},{"id":"c","en":"I went to Malaysia last year.","jp":"去年マレーシアに行きました。"},{"id":"d","en":"I wish I had been invited.","jp":"招待されていたらよかった。"}],"correct":"a","image":"/assets/questions/visual/july-27-03-splashed-water.webp","imageAlt":"A man playfully splashes water onto a woman.","visualAssetId":"july-27-03"}'::jsonb, false, 1),
      ('july-27', 'july-27-draft-visual-4', 29, 'See It', 'situation', '{"id":"july-27-draft-visual-4","format":"situation","type":"situation","section":"See It","topic":"taste","isOriginal":false,"hint":"Compare the person’s reaction to black coffee across repeated tastings over time.","hintJa":"時間をかけて何度かブラックコーヒーを飲む中で、反応がどう変わるか比べましょう。","explanation":"“Coffee can be an acquired taste.” is correct. Repeated tastings change the person’s reaction from dislike to genuine enjoyment of black coffee. “This dessert has a sophisticated flavor.” does not fit because the item is coffee, and the sequence shows learned preference rather than one refined dessert taste. “I have been to Malaysia.” does not fit because no travel memory or Malaysia landmark appears in the tasting sequence. “Don’t spill the beans.” does not fit because no secret is being revealed; the coffee beans and drink are literal taste cues.","explanationJa":"正解は「Coffee can be an acquired taste.」（コーヒーは慣れると好きになる味です。）です。繰り返し飲むうちに、ブラックコーヒーへの反応が苦手そうな表情から心から楽しむ表情へ変わっています。 「This dessert has a sophisticated flavor.」はこの場面とは一致しません。対象はコーヒーで、一度の洗練されたデザート味ではなく、好みの変化です。 「I have been to Malaysia.」はこの場面とは一致しません。試飲の連続場面に旅行経験やマレーシアの名所はありません。 「Don’t spill the beans.」はこの場面とは一致しません。秘密を漏らす場面ではなく、豆と飲み物は実際の味の手掛かりです。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"Coffee can be an acquired taste.","jp":"コーヒーは慣れると好きになる味です。"},{"id":"b","en":"This dessert has a sophisticated flavor.","jp":"このデザートは洗練された味です。"},{"id":"c","en":"I have been to Malaysia.","jp":"マレーシアへ行ったことがあります。"},{"id":"d","en":"Don’t spill the beans.","jp":"秘密をばらさないで。"}],"correct":"a","image":"/assets/questions/visual/july-27-04-acquired-taste.webp","imageAlt":"A person gradually learns to enjoy black coffee.","visualAssetId":"july-27-04"}'::jsonb, false, 1),
      ('july-27', 'july-27-draft-visual-5', 30, 'See It', 'situation', '{"id":"july-27-draft-visual-5","format":"situation","type":"situation","section":"See It","topic":"taste","isOriginal":false,"hint":"Use the elegant plating and the taster’s careful, impressed reaction to the flavor.","hintJa":"上品な盛り付けと、味を確かめて感心する人の反応を手掛かりにしましょう。","explanation":"“This dessert has a sophisticated flavor.” is correct. The refined presentation and the taster’s impressed response communicate a complex, elegant dessert flavor. “He plays tennis every week.” does not fit because no man, tennis equipment, or weekly routine appears at the dessert table. “I had eaten before he arrived.” does not fit because no arrival or ordering of two past events is shown; the dessert is being evaluated now. “I spilled coffee on my shirt.” does not fit because the dessert remains neatly plated and no coffee stain or accident appears.","explanationJa":"正解は「This dessert has a sophisticated flavor.」（このデザートは洗練された味です。）です。上品な盛り付けと感心した反応が、複雑で洗練されたデザートの味を示しています。 「He plays tennis every week.」はこの場面とは一致しません。デザートの食卓に男性・テニス用品・毎週の習慣はありません。 「I had eaten before he arrived.」はこの場面とは一致しません。誰かの到着や過去の前後関係ではなく、今デザートを味わっています。 「I spilled coffee on my shirt.」はこの場面とは一致しません。デザートはきれいに盛られ、コーヒーのしみや事故はありません。","prompt":"Which sentence best matches the illustration?","promptJa":"イラストの場面に最も合う英文を選んでください。","choices":[{"id":"a","en":"This dessert has a sophisticated flavor.","jp":"このデザートは洗練された味です。"},{"id":"b","en":"He plays tennis every week.","jp":"彼は毎週テニスをします。"},{"id":"c","en":"I had eaten before he arrived.","jp":"彼が着く前に食べていました。"},{"id":"d","en":"I spilled coffee on my shirt.","jp":"シャツにコーヒーをこぼしました。"}],"correct":"a","image":"/assets/questions/visual/july-27-05-sophisticated-dessert.webp","imageAlt":"An elegant dessert has a sophisticated flavor.","visualAssetId":"july-27-05"}'::jsonb, false, 1)
  )
  update public.review_questions question
  set position = source.position,
      section = source.section,
      format = source.format,
      payload = source.payload,
      is_original = source.is_original,
      points = source.points,
      updated_at = now()
  from source
  join public.review_lessons lesson on lesson.slug = source.lesson_slug
  where question.lesson_id = lesson.id
    and question.stable_key = source.stable_key;

  get diagnostics updated_count = row_count;
  if updated_count <> 85 then
    raise exception 'Visual question correction incomplete: expected 85 updated rows, updated %.', updated_count;
  end if;
end;
$visuals$;

update public.review_lessons
set content_version = greatest(content_version, 4),
    updated_at = now()
where slug in (
  'june-28', 'june-29', 'june-30', 'july-04', 'july-05', 'july-06',
  'july-07', 'july-11', 'july-12', 'july-13', 'july-18', 'july-19',
  'july-22', 'july-23', 'july-25', 'july-26', 'july-27'
);
